export default {'one-health--oh-amr':[['one-health--oh-amr--ความหมายและขนาดของปัญหา','ความหมายและขนาดของปัญหา','ความหมายและขนาดของปัญหา \n who นิยามว่า amr คือ การที่ pathogen เปลี่ยนแปลงตัวเองจนไม่ตอบสนองต่อยาต้านจุลชีพ ทำให้การรักษาไม่มีประสิทธิภาพ โดยการบรรยายเน้นที่แบคทีเรียเป็นหลัก \n ในมุมระบาดวิทยาเรียกเชื้อที่ผิดไปจากประชากรปกติว่า non-wild type ส่วนในทางคลินิกเรียกว่า decreased susceptibility \n amr อยู่ได้ทั้งในคน สัตว์ และสิ่งแวดล้อม และส่งผลถึงกันและกัน \n ประมาณ 73% ของยาปฏิชีวนะทั่วโลกถูกใช้ใน food animals และกำลังเพิ่มขึ้นทุกปี โดยเฉพาะในเอเชีย \n สัตว์ที่ใช้ยามากที่สุดเรียงลำดับ สุกร มากกว่า ไก่ มากกว่า โค \n เอกสารพิมพ์คำว่า non-wide type ซึ่งเป็นการพิมพ์คลาดเคลื่อนของ non-wild type ให้ใช้คำที่ถูกต้องในการตอบ \n จุดที่ต้องระวัง: ผู้สรุปบันทึกว่าข้อสอบของรุ่นก่อนหน้ามีข้อที่ถามว่า amr ครอบคลุมทั้งแบคทีเรียและไวรัสหรือไม่ และคีย์ของรุ่นนั้นให้ยึดตามที่บรรยายซึ่งเน้นแบคทีเรีย แต่ในทางวิชาการ นิยาม antimicrobial resistance ของ who ครอบคลุมแบคทีเรีย ไวรัส เชื้อรา และปรสิต ส่วน antibiotic resistance จึงจะจำกัดที่แบคทีเรีย ให้ยึดถ้อยคำที่ผู้บรรยายปีนี้ใช้เป็นหลัก \n การใช้ยาต้านจุลชีพในสัตว์มีปริมาณมากกว่าในคนราวสามเท่า ซึ่งสอดคล้องกับตัวเลขที่บรรยายว่าราวสามในสี่ของยาปฏิชีวนะทั่วโลกถูกใช้ใน food animals และสัดส่วนยาที่พบการดื้อเกินร้อยละ 50 เพิ่มขึ้นทั้งในไก่และสุกรระหว่างปี 2000 ถึง 2018 โดยจีนและอินเดียเป็น hotspot ใหญ่ที่สุด'],['one-health--oh-amr--ยา-last-line-และการจัดกลุ่มของ-who','ยา last line และการจัดกลุ่มของ WHO','ยา last line และการจัดกลุ่มของ who \n last line abo คือยาทางเลือกสุดท้ายไว้รักษา mdr bacteria เช่น colistin (polymyxin b), imipenem, 4th generation cephalosporins \n bsbl (broad-spectrum beta-lactamase) เป็นเอนไซม์ที่แบคทีเรียสร้างขึ้นเพื่อทำลายยา beta-lactams และ cephalosporins ทั้งรุ่นเก่าและรุ่นใหม่ \n who แบ่งยาออกเป็น 3 กลุ่ม \n ยาที่ควรสงวนไว้ ใช้ในคนเท่านั้น \n ยาที่ใช้ได้ทั้งคนและสัตว์ แต่ต้องใช้อย่างระมัดระวัง โดยเฉพาะกลุ่ม hpcia (high priority critically important antimicrobials) เช่น 3rd และ 4th generation cephalosporins, quinolones, polymyxins \n ยาที่ใช้ในสัตว์เท่านั้น ไม่ใช้ในคน \n ตัวอย่างยา last line กับเชื้อเป้าหมายจากตารางในเอกสาร \n colistin, polymyxin b กับ mdr klebsiella, acinetobacter, pseudomonas \n linezolid, tedizolid กับ mrsa, vre \n vancomycin, teicoplanin กับ mrsa และ enterococcus ที่ดื้อยา \n imipenem, meropenem, doripenem กับ esbl-producers และ mdr gram-negatives \n cefepime, ceftaroline กับ mdr enterobacteriaceae และ mrsa \n daptomycin กับ mrsa, vre \n tigecycline กับ cre, mrsa, vre \n fosfomycin, cefiderocol กับ cre, mdr pseudomonas, acinetobacter \n ผู้สรุปบันทึกว่าข้อสอบรุ่นก่อนหน้ามีทั้งข้อที่ถามว่าควรสงวน last line ไว้ใช้ในคนหรือไม่ และข้อที่หลอกว่าสงวนไว้ใช้ในสัตว์เลี้ยงแต่ห้ามใช้ในปศุสัตว์ หลักที่ถูกต้องคือ สงวนไว้สำหรับคน \n who จัด quinolones และ cephalosporins รุ่นที่ 3 และ 4 ไว้ในกลุ่ม highest priority critically important antimicrobials ตรงตามที่เอกสารระบุ แต่รายการเดียวกันของ who ยังรวม macrolides และ ketolides กับ glycopeptides ไว้ด้วย ซึ่งเอกสารไม่ได้กล่าวถึง \n polymyxins ซึ่งรวม colistin ถูกจัดเป็นยากลุ่มสุดท้ายที่เหลืออยู่สำหรับเชื้อแกรมลบดื้อยาหลายขนาน จึงเป็น last line ตามที่เอกสารระบุ'],['one-health--oh-amr--กลไกพันธุกรรมของการดื้อยา','กลไกพันธุกรรมของการดื้อยา','กลไกพันธุกรรมของการดื้อยา \n plasmid-mediated resistance \n การดื้อ colistin เกิดจากยีน mcr-1 ที่อยู่บนพลาสมิด \n การดื้อ carbapenems เกิดจากยีน carbapenemase บนพลาสมิด \n bsbls เป็นเอนไซม์ที่ทำให้ดื้อต่อ last line ทางอ้อม โดยไปทำลายโมเลกุลของยา โดยเฉพาะ 3rd และ 4th generation cephalosporins ยีนที่สร้างเอนไซม์นี้ก็อยู่บนพลาสมิดเช่นกัน \n chromosomal mutation \n fluoroquinolones เป็นยา 2nd line การดื้อเกิดจาก mutation บนโครโมโซม ทำให้ยาจับกับ dna ของเชื้อไม่ได้ \n การกลายพันธุ์บนโครโมโซม ไม่ค่อยแพร่ข้ามชนิดเชื้อ แต่แพร่ตามการแบ่งตัวของเชื้อเอง จึงช้ากว่าการแพร่ผ่านพลาสมิด \n การดื้อ colistin จากยีน mcr-1 อยู่บนพลาสมิดและถ่ายทอดข้ามเชื้อได้จริงโดย conjugation รวมถึงคงอยู่ได้ใน klebsiella pneumoniae และ pseudomonas aeruginosa ต่างจากการดื้อ polymyxin เดิมที่เกิดจาก chromosomal mutation เท่านั้น'],['one-health--oh-amr--ผลของการให้ยา-r-plasmid-และ-mdr','ผลของการให้ยา R-plasmid และ MDR','ผลของการให้ยา r-plasmid และ mdr \n การให้ยาปฏิชีวนะทำให้เกิด 3 อย่าง \n emergence เชื้อเกิดการดื้อขึ้นจากการเจอยา \n selection ตัวที่ดื้อรอดมาแล้วเพิ่มจำนวน \n distribution ตัวที่ดื้อถ่ายทอดยีนให้เชื้อชนิดเดียวกันหรือต่างชนิดก็ได้ \n r-plasmid \n พลาสมิดที่มียีนดื้อยาหลายตัว ถ่ายทอดแบบ horizontal transfer ให้เชื้อตัวอื่นผ่าน conjugation \n เชื้อที่รับ dna จาก donor ได้สำเร็จเรียกว่า transconjugant \n vertical transfer มักเกิดจาก mutation บนโครโมโซมแล้วส่งต่อให้ลูกหลาน \n inc group (incompatibility) คือตระกูลของพลาสมิด ถ้าอยู่กลุ่มเดียวกันแสดงว่ามีพันธุกรรมคล้ายกัน จึงใช้เป็น epidemiological marker ในการเฝ้าระวัง amr ได้ \n mdr bacteria \n นิยามคือเชื้อที่ ดื้อยาตั้งแต่ 3 classes ขึ้นไป \n co-selection คือยาชนิดเดียวคัดเลือกจนเชื้อดื้อยาหลายชนิดพร้อมกัน เพราะยีนดื้อยาหลายตัวอยู่บนพลาสมิดวงเดียวกัน ใช้ยา a แล้วเชื้อที่รอดก็พกยีนดื้อยา b ติดมาด้วย \n cross resistance คือกลไกเดียวทำให้ดื้อยาหลายชนิดแม้คนละกลุ่ม เช่น efflux pump ตัวเดียวปั๊มยาได้หลายชนิดออกจากเซลล์ \n นิยามสากลของ mdr คือเชื้อที่ไม่ไวต่อยาอย่างน้อย 1 ตัวใน 3 antimicrobial categories ขึ้นไป ซึ่งตรงกับที่เอกสารระบุว่าดื้อยาตั้งแต่ 3 กลุ่มขึ้นไป โดยจุดสำคัญคือใช้คำว่า non-susceptible ไม่ใช่ resistant เต็มขั้น และนับเป็น category ไม่ใช่ตัวยา \n cross resistance ผ่าน efflux pump เป็นกลไกจริง โดยการ overexpress multidrug efflux pump acrab-tolc ทำให้เชื้อดื้อยาได้หลายชนิดพร้อมกันจากกลไกเดียว'],['one-health--oh-amr--amr-surveillance-และงานวิจัยที่ยกมา','AMR surveillance และงานวิจัยที่ยกมา','amr surveillance และงานวิจัยที่ยกมา \n commensal e. coli ซึ่งเป็นแบคทีเรียแกรมลบประจำถิ่น คือเชื้อที่แนะนำให้ใช้เฝ้าระวัง เพราะเกิด amr ได้ง่าย \n การดื้อยาใน e. coli สะท้อนการใช้ยาจริงในฟาร์ม เพราะเป็น normal flora ที่โดน selection pressure ทุกครั้งที่ฟาร์มใช้ยา \n เชื้ออื่นที่ควรดูด้วยคือ salmonella, campylobacter, enterococcus แต่ไม่สะท้อนภาพได้ชัดเท่า e. coli \n co-selection ทำให้ยังพบการดื้อ chloramphenicol ได้ แม้จะเลิกใช้ยานี้ไปแล้ว \n การศึกษาเน้น phenotype มากกว่าการทำ wgs เพราะเชื้ออาจมียีนดื้อยาแต่ไม่แสดงออก ดังนั้น ast ยังสำคัญที่สุดต่อการรักษา \n งานวิจัย e. coli ในเป็ด \n พบยีนดื้อ colistin mcr-1.1 บน inci2 plasmid ในเป็ดเนื้อของไทย \n พลาสมิดมีความเหมือนกับพลาสมิดที่พบใน คน สุกร ไก่ และน้ำเสีย อย่างมาก \n แสดงถึงการแพร่ยีนดื้อยาแบบ horizontal ข้ามชนิดสัตว์ ข้ามฟาร์ม และข้ามประเทศ \n งานวิจัย salmonella และ phylogenetic tree \n พลาสมิด incfii/fib ที่แบก esbl gene พบใน e. coli จากเป็ดและสุกร และพบใน salmonella จากสุกรและคน \n โครงสร้างพลาสมิดจากสัตว์และคนเหมือนกันมาก บ่งชี้การแพร่ข้าม host \n e. coli จากเป็ดเนื้อของไทยมี genome ใกล้เคียงกับ e. coli ที่พบในคนจากสหราชอาณาจักรและจีน \n ยีนดื้อยาหลายตัวมาเป็น gene cluster การใช้ยาจึงเกิด co-selection ได้ \n งานวิจัย amr ในอากาศของฟาร์มสุกร \n ใช้ metagenomic analysis กับตัวอย่างฝุ่นในอากาศ \n พบทั้งแบคทีเรียและยีนดื้อยาจำนวนมากในอากาศ จึง มีผลต่อสุขภาพคนที่ทำงานในฟาร์ม \n ขั้นตอนตามแผนภาพ: เก็บตัวอย่างฝุ่นในอากาศ นับจำนวนแบคทีเรียทั้งหมด แยกและระบุเชื้อเป้าหมาย (eskape, salmonella, e. coli) ทำ antimicrobial susceptibility testing และสกัด dna เพื่อทำ metagenomic sequencing ดู bacterial communities และ resistome \n woah กำหนดให้ใช้ e. coli และ enterococci ที่เป็น commensal เป็น indicator ในโปรแกรมเฝ้าระวัง amr เพราะสะท้อนแหล่งสะสมของยีนดื้อยาที่อาจถ่ายทอดไปยังเชื้อก่อโรค และควรเก็บจากสัตว์สุขภาพดีที่โรงฆ่าเพื่อให้เปรียบเทียบกันได้ \n งานวิจัยในเป็ดเนื้อของไทยพบยีน mcr-1 อยู่บนพลาสมิดกลุ่ม inci2 ทั้งหมด และถ่ายทอดโดย conjugation ได้จริง โดยเชื้อ mcr-positive e. coli ส่วนใหญ่ถึงร้อยละ 89.2 เป็น mdr \n ฝุ่นในอากาศของฟาร์มสุกรและฟาร์มสัตว์ปีกมี resistome ที่หลากหลายและมีปริมาณยีนดื้อยาสูงกว่าที่พบในอุจจาระสัตว์ สัมพันธ์กับปริมาณการใช้ยาในฟาร์ม และการสัมผัสฝุ่นฟาร์มอาจมีส่วนต่อ resistome ของเกษตรกร ตรงกับที่เอกสารสรุปจากการทำ metagenomic analysis ของฝุ่นในอากาศ'],['one-health--oh-amr--รูปแบบข้อสอบของรุ่นก่อนหน้า','รูปแบบข้อสอบของรุ่นก่อนหน้า','รูปแบบข้อสอบของรุ่นก่อนหน้า \n ผู้สรุปบันทึกว่าหัวข้อ amr ของรุ่นก่อนหน้าออกเป็น ข้อถูกหรือผิด 10 ข้อ เป็นภาษาอังกฤษทั้งหมด และมีข้อความหลอกหลายจุด จึงควรอ่านศัพท์เทคนิคภาษาอังกฤษให้คล่อง ข้อสอบปีนี้อาจต่างออกไป']],'one-health--oh-collaboration':[['one-health--oh-collaboration--มุมมอง-one-health-ต่อการจัดการของเสีย','มุมมอง One Health ต่อการจัดการของเสีย','มุมมอง one health ต่อการจัดการของเสีย \n pathogens จากการปนเปื้อนของมูลสัตว์ในฟาร์มปศุสัตว์ \n agrochemicals จากการเกษตรแบบเข้มข้น \n sediments จากการชะล้างพังทลายของดิน \n microplastics จากกิจกรรมของมนุษย์หลากหลายรูปแบบ \n รายงานทบทวนระดับโลกของ fao ระบุตัวการหลักของมลพิษทางน้ำจากภาคเกษตรว่าได้แก่ ธาตุอาหาร สารกำจัดศัตรูพืช เกลือ ตะกอน สารอินทรีย์ เชื้อก่อโรค และ emerging pollutants เช่น ยาปฏิชีวนะและฮอร์โมนเร่งการเจริญเติบโต ซึ่งครอบคลุมสามในสี่รายการที่เอกสารยกมา ยกเว้น microplastics ที่ไม่ได้อยู่ในรายการนี้'],['one-health--oh-collaboration--หลัก-3-ประการและการลดของเสีย','หลัก 3 ประการและการลดของเสีย','หลัก 3 ประการและการลดของเสีย \n reduce ลดปริมาณของเสียจากแหล่งกำเนิด \n reuse นำของเสียไปใช้ประโยชน์ เป็นอาหารสัตว์ ปุ๋ยอินทรีย์ หรือแหล่งพลังงาน \n treatment บำบัดและจัดการของเสีย โดยเฉพาะการบำบัดน้ำเสีย \n แนวทางการ reduce \n ลดของเสียจากแหล่งกำเนิด เพิ่มประสิทธิภาพการผลิต และปรับปรุงวิธีการจัดการฟาร์ม \n ทำให้สัตว์ขับถ่ายของเสียลดลง \n เพิ่มอัตราการเปลี่ยนอาหารเป็นเนื้อ (fcr) เพื่อลดต้นทุนอาหารสัตว์ \n ใช้ทรัพยากรและพลังงานอย่างมีประสิทธิภาพ \n การจัดการโรงเรือน \n การวางผังฟาร์มและโรงเรือน การจัดพื้นที่และประเภทโรงเรือน \n ความเหมาะสมในการออกแบบตามชนิดและจำนวนสัตว์ รวมถึงการสุขาภิบาล \n วิธีการและความถี่ของการล้างทำความสะอาดคอก โรงเรือน และตัวสัตว์ เอกสารระบุปริมาณน้ำใช้ราว 25 ลิตรต่อสุกร 1 ตัวต่อวัน และ 150 ถึง 200 ลิตรต่อโคนม 1 ตัวต่อวัน \n ประโยชน์ของการลดปริมาณของเสีย \n ลดต้นทุนการกำจัดและบำบัดของเสีย \n ลดต้นทุนการผลิตและเพิ่มผลกำไรให้ฟาร์ม \n ส่งเสริมสุขภาพสัตว์ในฟาร์ม \n อนุรักษ์สิ่งแวดล้อมและพลังงาน และสร้างภาพลักษณ์ที่ดีให้ฟาร์ม \n การลดของเสียที่แหล่งกำเนิดด้วยการจัดการอาหารทำได้จริงและวัดผลได้ สุกรขุนที่ได้สูตรอาหารลดโปรตีนและฟอสฟอรัสขับถ่ายไนโตรเจนน้อยลงร้อยละ 28.3 และฟอสฟอรัสน้อยลงร้อยละ 15.1 โดยปริมาณอาหารที่กินและอัตราการเจริญเติบโตไม่ต่างจากกลุ่มควบคุม \n แนวทาง reuse ที่ให้นำของเสียไปใช้เป็นปุ๋ยอินทรีย์มีฐานทางวิชาการรองรับ เอกสาร fao ระบุให้เกษตรกรประเมินค่าธาตุอาหารในมูลสัตว์แล้วลดปริมาณปุ๋ยเคมีลงตามสัดส่วน และการปรับสูตรอาหารเป็นวิธีหนึ่งในการทำให้ธาตุอาหารเข้าออกฟาร์มสมดุลขึ้น'],['one-health--oh-collaboration--เกณฑ์การเลือกและออกแบบระบบบำบัด','เกณฑ์การเลือกและออกแบบระบบบำบัด','เกณฑ์การเลือกและออกแบบระบบบำบัด \n ชนิดและจำนวนสัตว์ในฟาร์ม \n สภาพภูมิศาสตร์และขนาดพื้นที่ของฟาร์ม \n ความต้องการคุณภาพของน้ำทิ้งที่ผ่านการบำบัด \n แผนการใช้ประโยชน์จากผลผลิตของระบบบำบัด \n งบประมาณ ค่าใช้จ่ายในการดำเนินการและบำรุงรักษา \n คู่มือของ usda ระบุว่าถ้าพื้นที่สำหรับนำของเสียไปใช้ประโยชน์มีจำกัด เจ้าของฟาร์มอาจจำเป็นต้องเลือกกระบวนการบำบัดที่ลดปริมาณไนโตรเจนในของเสียลง ยืนยันว่าขนาดพื้นที่ของฟาร์มและแผนการใช้ประโยชน์จากผลผลิตเป็นเกณฑ์ที่กำหนดชนิดของระบบบำบัดโดยตรง \n ลักษณะของของเสียที่ต้องจัดการขึ้นกับสภาพภูมิอากาศ ชนิดของสัตว์ ปริมาณน้ำที่สัตว์กิน และชนิดอาหาร โดยความเข้มข้นของ total solids เป็นคุณสมบัติหลักที่กำหนดว่าจะจัดการของเสียนั้นได้อย่างไร สนับสนุนเกณฑ์ชนิดและจำนวนสัตว์ในฟาร์ม รวมถึงปัจจัยภายนอกด้านสภาพภูมิอากาศตามที่สรุประบุ \n แผนการบำบัดของเสียต้องวิเคราะห์คุณลักษณะของของเสียก่อนบำบัด กำหนดคุณลักษณะที่ต้องการหลังบำบัด และต้องเลือกชนิด ขนาดโดยประมาณ ตำแหน่งที่ตั้ง ค่าติดตั้ง รวมถึงค่าใช้จ่ายในการบริหารจัดการกระบวนการบำบัด ยืนยันว่างบประมาณและค่าดำเนินการเป็นเกณฑ์ที่ต้องคิดตั้งแต่ขั้นออกแบบ \n ในบริบทไทย เกณฑ์คุณภาพน้ำทิ้งไม่ใช่ตัวเลือกแต่เป็นข้อกำหนดตามกฎหมาย โดยกรมปศุสัตว์อ้างอิงพระราชบัญญัติส่งเสริมและรักษาคุณภาพสิ่งแวดล้อมแห่งชาติ พ.ศ. 2535 กำหนดดัชนีคุณภาพน้ำทิ้งฟาร์มสุกรไว้ เช่น ph 5.5-9, bod ไม่เกิน 40 หรือ 80 mg/l, cod ไม่เกิน 250 หรือ 350 mg/l, tss ไม่เกิน 150 หรือ 200 mg/l, tkn ไม่เกิน 120 หรือ 200 mg/l และ tp ไม่เกิน 5 mg/l โดยแบ่งประเภทฟาร์ม ก, ข, ค ตามจำนวนหน่วยปศุสัตว์ (ก 10,000 / ข 5,000 / ค 500 หรือ 100) จึงยืนยันทั้งเกณฑ์จำนวนสัตว์ เกณฑ์คุณภาพน้ำทิ้ง และปัจจัยภายนอกด้านกฎหมาย'],['one-health--oh-collaboration--ระบบบ่อบำบัดกับระบบก๊าซชีวภาพ','ระบบบ่อบำบัดกับระบบก๊าซชีวภาพ','ระบบบ่อบำบัดกับระบบก๊าซชีวภาพ \n ระบบบ่อบำบัด (ponding system) \n ก่อสร้างและบำรุงรักษาง่าย ค่าใช้จ่ายน้อยกว่า \n เป็นบ่อรองรับน้ำเสียต่อเนื่องกัน 3 ถึง 4 บ่อ ได้แก่ บ่อไร้อากาศ (anaerobic pond), บ่อกึ่งไร้อากาศ (facultative pond), บ่อใช้อากาศ (aerobic pond) และบ่อปรับเสถียร (stabilization pond) \n ระบบก๊าซชีวภาพ (biogas system) \n อาศัยจุลินทรีย์แบบไม่ใช้อากาศเป็นหลัก ใช้เวลาย่อยสลายสารอินทรีย์นาน \n ออกแบบเพื่อผลิตพลังงานทดแทนมากกว่าเพื่อการบำบัด น้ำที่ผ่านการบำบัดยังมีสารอินทรีย์มาก จึงต้องบำบัดขั้นหลังเพิ่มเติม \n fixed dome digester ระบบโดมคงที่ \n uasb (upflow anaerobic sludge blanket reactor) มีประสิทธิภาพกำจัดของเสียสูงราว 70 ถึง 80% \n cigar (covered lagoon ground anaerobic reactor) ระบบบ่อคลุม ใช้เวลานานในการบำบัด มากกว่า 120 วัน \n ตารางเปรียบเทียบ \n ค่าก่อสร้าง: บ่อบำบัดต่ำ ก๊าซชีวภาพสูง \n พื้นที่ก่อสร้าง: บ่อบำบัดใช้มาก ก๊าซชีวภาพใช้น้อยกว่า \n การบำรุงรักษาระบบ: บ่อบำบัดง่าย ก๊าซชีวภาพยาก \n ผลตอบแทน: บ่อบำบัดปานกลาง ก๊าซชีวภาพสูง \n คุณภาพน้ำทิ้ง: บ่อบำบัดผ่านมาตรฐาน ส่วนก๊าซชีวภาพไม่ผ่าน จึงต้องมีการบำบัดขั้นหลัง \n ระบบบ่อบำบัดน้ำเสียแบบธรรมชาติทำงานเป็นบ่อต่อเนื่องกันหลายบ่อ โดยลำดับมาตรฐานคือ anaerobic pond แล้วต่อด้วย facultative pond แล้วจึงเป็น maturation pond และประสิทธิภาพจะเพิ่มขึ้นตามลำดับบ่อ เช่น การกำจัดไข่พยาธิได้เฉลี่ยร้อยละ 94 ในบ่อไร้อากาศและร้อยละ 99.9 ในบ่อกึ่งไร้อากาศ'],['one-health--oh-collaboration--มาตรฐานน้ำทิ้งจากฟาร์มสุกร','มาตรฐานน้ำทิ้งจากฟาร์มสุกร','มาตรฐานน้ำทิ้งจากฟาร์มสุกร \n ph value 5.5 ถึง 9 ทั้งสองประเภท \n bod ประเภท ก ไม่เกิน 60 ส่วนประเภท ข และ ค ไม่เกิน 100 มิลลิกรัมต่อลิตร \n suspended solids (ss) ประเภท ก ไม่เกิน 150 ส่วนประเภท ข และ ค ไม่เกิน 200 มิลลิกรัมต่อลิตร \n cod ประเภท ก ไม่เกิน 300 ส่วนประเภท ข และ ค ไม่เกิน 400 มิลลิกรัมต่อลิตร \n tkn ประเภท ก ไม่เกิน 120 ส่วนประเภท ข และ ค ไม่เกิน 200 มิลลิกรัมต่อลิตร \n ประเภท ก เข้มงวดกว่าเพราะเป็นฟาร์มขนาดใหญ่ ถ้าปล่อยน้ำทิ้งเกินมาตรฐานผลกระทบย่อมมากกว่า ผู้สรุปบันทึกว่าข้อสอบรุ่นก่อนหน้าถามในเชิงว่าอะไร ไม่ใช่ พารามิเตอร์ในมาตรฐานนี้ โดยมีตัวหลอกคือจำนวนสุกร \n มาตรฐานน้ำทิ้งจากฟาร์มสุกรของไทยควบคุมพารามิเตอร์ตามที่เอกสารสรุประบุจริง คือ ph 5.5 ถึง 9.0 ทั้งสองกลุ่ม ส่วนฟาร์มขนาดใหญ่เข้มกว่าฟาร์มขนาดกลางและเล็ก โดย bod 60 เทียบกับ 100 ss 150 เทียบกับ 200 cod 300 เทียบกับ 400 และ tkn 120 เทียบกับ 200 มิลลิกรัมต่อลิตร']],'one-health--oh-concept':[['one-health--oh-concept--gmo-นิยามและตัวอย่าง','GMO นิยามและตัวอย่าง','gmo นิยามและตัวอย่าง \n bt corn ใส่ยีนจากแบคทีเรีย bacillus thuringiensis ที่ผลิต toxin ฆ่าแมลงเข้าไปในข้าวโพด \n roundup ready soybean ถั่วเหลืองที่ได้ยีนจากแบคทีเรียให้ ทนต่อยาฆ่าหญ้าที่มี glyphosate \n aquadvantage salmon ใส่ยีนสร้าง growth hormone จากแซลมอนชินุกเข้าไปในแซลมอนแอตแลนติก ทำให้โตเร็วและโตได้ทุกฤดูกาล \n gm e. coli ที่ผลิต bovine somatotropin (bst) นำฮอร์โมนไปฉีดวัวเพื่อให้หลั่งน้ำนมมากขึ้น \n bt corn คือข้าวโพดดัดแปรพันธุกรรมที่แสดงออก crystalline (cry) protein toxin ของ bacillus thuringiensis เพื่อป้องกันหนอนเจาะลำต้นข้าวโพด (european corn borer, ostrinia nubilalis) ตรงตามที่เอกสารระบุ \n aquadvantage salmon เป็นแซลมอนแอตแลนติกที่ได้รับ growth hormone gene จากแซลมอนชินุก (chinook salmon) ทำให้โตเร็วขึ้นจนถึงขนาดตลาดในเวลาราวครึ่งหนึ่งของแซลมอนแอตแลนติกปกติ'],['one-health--oh-concept--ผลกระทบของ-gmo-ต่อคน','ผลกระทบของ GMO ต่อคน','ผลกระทบของ gmo ต่อคน \n ผลกระทบทางตรง \n ข้อกังวลหลักคือ substantial equivalence คือความปลอดภัยของพืช gm ต้องเทียบเท่ากับพืชปกติ โดยเทียบจาก toxicity, nutrition, allergenicity \n ข้อเสียคือประเด็น food security และการบริโภคที่เพิ่มขึ้น \n fda ทำ food safety assessment 4 อย่างคือ molecular characterization, nutrition, toxicological และ allergenicity assessment \n fda พบว่า gmo มีผลต่อคนน้อยมาก แต่ผู้บริโภคควรมีสิทธิเลือก อาหารที่มีส่วนประกอบ gmo ตั้งแต่ 5% ขึ้นไปต้องติดฉลาก \n ผู้สรุปบันทึกว่ามีข้อหลอกที่ใส่ carcinogenicity assessment เพิ่มเข้ามาในรายการ 4 อย่างของ fda \n ผลกระทบทางอ้อมด้านสุขภาพ \n ht trait ทำให้วัชพืชทนยาฆ่าหญ้ามากขึ้น คนปลูกจึงเสี่ยงได้รับสารพิษ หรือต้องเปลี่ยนไปใช้ยาที่แรงขึ้น \n bt trait ปัจจุบันช่วยลดการใช้ยาฆ่าแมลง แต่ถ้าแมลงดื้อต่อ bt ก็อาจกลับไปใช้ยาฆ่าแมลงมากขึ้น \n คนผลิตอาหาร คนเลี้ยงสัตว์ และผู้บริโภค มีทั้งได้และเสียประโยชน์ \n ผลกระทบทางอ้อมด้านเศรษฐกิจ \n คนปลูกได้มูลค่าเพิ่ม แต่เกิด การผูกขาดโดยบริษัทเจ้าของเทคโนโลยี ที่กำหนดราคาได้ \n ถ้าแข่งขันด้านราคาระหว่าง gm กับ non-gm สุดท้ายผู้ที่ได้ประโยชน์คือ ผู้บริโภค \n การประเมินความปลอดภัยของพืชและอาหาร gm ใช้แนวคิด substantial equivalence คือเทียบกับพืช non-gm ที่เป็น isogenic counterpart โดยเปรียบเทียบองค์ประกอบทางเคมีในวงกว้างและสมรรถนะของสัตว์ ตรงตามที่เอกสารระบุ \n กฎการติดฉลาก gmo ของไทยตามประกาศกระทรวงสาธารณสุข ฉบับที่ 251 พ.ศ. 2545 ใช้เกณฑ์ร้อยละ 5 จริง แต่เป็นร้อยละ 5 ของแต่ละส่วนประกอบที่เป็นส่วนประกอบหลัก 3 อันดับแรก และส่วนประกอบนั้นต้องมีปริมาณตั้งแต่ร้อยละ 5 ของน้ำหนักผลิตภัณฑ์ อีกทั้งบังคับเฉพาะถั่วเหลืองและข้าวโพดดัดแปรพันธุกรรมกับผลิตภัณฑ์ของทั้งสองชนิด ไม่ใช่อาหารทุกชนิดที่มีส่วนประกอบ gmo'],['one-health--oh-concept--ผลกระทบของ-gmo-ต่อสัตว์และสิ่งแวดล้อม','ผลกระทบของ GMO ต่อสัตว์และสิ่งแวดล้อม','ผลกระทบของ gmo ต่อสัตว์และสิ่งแวดล้อม \n ผลต่อสัตว์คล้ายกับคน แต่ food safety assessment ในสัตว์ยังไม่มีหลักฐานชัดเจนถึง adverse effects ในสัตว์ที่กิน gmo \n ผลทางตรงต่อสิ่งแวดล้อมด้านดี: ถ้าผลผลิตดีขึ้น คนก็ไม่ต้องถางป่าเพิ่ม ลดแก๊สเรือนกระจกจากเกษตรกรรม \n ผลทางตรงด้านเสีย: ถ้าผลผลิตดี ก็อาจถางป่าเพิ่ม และปลูกพืชชนิดเดิมซ้ำจนทำให้ biodiversity ลดลง \n ผลทางอ้อม: ht trait ทำให้ใช้ยาฆ่าหญ้ามากขึ้น เกิด spray drift เป็นพิษต่อดิน น้ำ และสัตว์ที่ไม่ใช่เป้าหมาย ส่วน bt trait ก็เกิด spray drift ได้เช่นกันถ้าใช้มาก \n environmental assessment มีอยู่ แต่ ขาดการประเมินระยะยาว และยังไม่มีข้อมูลว่าการถางป่าเพื่อปลูกพืช gm ในระดับโลกลุกลามไปแค่ไหน \n prevention and control \n crop rotation ปลูกพืชหมุนเวียนสลับกับ gm crop เพื่อ ลด selective pressure ของยีนต้านทาน \n diversification ปลูก gm crop หลายชนิดเพื่อไม่ให้ทนสารเคมีตัวเดียวกันทั้งหมด \n pesticide regulation ห้ามใช้ในบางพื้นที่ \n pesticide monitoring ตรวจในอาหาร ถ้าพบมากขึ้นอาจแปลว่าเริ่มมีการดื้อและใช้ยามากขึ้น \n นโยบายไทย: ห้ามปลูกพืช gm เชิงพาณิชย์ แต่อนุญาตให้นำเข้าเป็นวัตถุดิบเพื่อการแปรรูปอาหาร และต้องระบุว่าเป็น gm crop \n ข้อมูลการทดลองที่มีอยู่ยังไม่พบผลเสียต่อสัตว์หรือผลิตภัณฑ์จากสัตว์ที่ได้รับอาหารจากพืช gm ซึ่งตรงกับที่เอกสารระบุว่ายังไม่มีหลักฐานชัดเจนถึง adverse effects ในสัตว์ที่กิน gmo \n การใช้พืช gm ลดการใช้สารกำจัดศัตรูพืชลงเฉลี่ยร้อยละ 37 และการลดลงนี้มากกว่าในพืชกลุ่ม insect-resistant (bt) เมื่อเทียบกับพืชกลุ่ม herbicide-tolerant ซึ่งสนับสนุนทั้งข้อที่ว่า bt trait ช่วยลดการใช้ยาฆ่าแมลง และข้อที่ว่า ht trait ให้ประโยชน์ด้านนี้น้อยกว่า \n ความกังวลเรื่องแมลงดื้อต่อ bt ไม่ใช่แค่สมมติฐาน มีการตรวจพบ ostrinia nubilalis ที่ดื้อต่อ cry1ab ทั้งจากการเฝ้าระวังในภาคสนามและจากการคัดเลือกในห้องปฏิบัติการแล้ว จึงเป็นเหตุผลรองรับมาตรการ crop rotation และ diversification เพื่อลด selective pressure'],['one-health--oh-concept--แก๊สและมลพิษจากระบบการผลิตอาหาร','แก๊สและมลพิษจากระบบการผลิตอาหาร','แก๊สและมลพิษจากระบบการผลิตอาหาร \n greenhouse gases (ghg) \n carbon dioxide (co2) จากเชื้อเพลิงฟอสซิลและชีวมวล \n methane (ch4) จากปศุสัตว์ เกษตรกรรม และการย่อยสลายของเสียอินทรีย์ \n nitrous oxide (n2o) จากปุ๋ย อุตสาหกรรม และการบำบัดน้ำเสีย \n fluorinated gases เป็น subset ของ vocs ใช้ในอุตสาหกรรม มีปริมาณน้อยแต่กักเก็บความร้อนได้มากกว่าแก๊สเรือนกระจกอื่น เพราะมี gwp สูง \n vocs และ pm \n volatile organic compounds (vocs) ระเหยง่ายแต่ละลายน้ำได้น้อย เช่น สี ยาฆ่าแมลง ผลิตภัณฑ์ในบ้าน \n แอมโมเนียไม่จัดเป็น voc เพราะละลายน้ำได้ดีและไม่ใช่สารประกอบอินทรีย์ \n particulate matter (pm) คืออนุภาคของแข็งและหยดของเหลว เช่น pm2.5 และ pm10 \n เอกสารเขียนเหตุผลของแอมโมเนียว่า ไม่มี c, h ซึ่งคลาดเคลื่อน เพราะ nh3 มีไฮโดรเจนแต่ไม่มีคาร์บอน เหตุผลที่ถูกต้องคือไม่มีคาร์บอนจึงไม่ใช่สารประกอบอินทรีย์ บวกกับการละลายน้ำได้ดี \n food loss กับ food waste \n food loss เกิดได้ทุกขั้นตอนของการผลิตและเก็บรักษา เช่น ความชื้น ความร้อน เชื้อรา หนูและแมลง หรือความเสียหายระหว่างขนส่ง \n food waste คืออาหารที่เสียหรือถูกทิ้งโดยผู้ค้าปลีกและผู้บริโภค เช่น หมดอายุ หรือเข้าใจผิดระหว่าง best before กับ expired \n นิยามทางกฎหมายของ volatile organic compounds คือสารประกอบของคาร์บอนที่เข้าร่วมปฏิกิริยาโฟโตเคมีในบรรยากาศ โดยยกเว้นคาร์บอนมอนอกไซด์ คาร์บอนไดออกไซด์ กรดคาร์บอนิก คาร์ไบด์และคาร์บอเนตของโลหะ และแอมโมเนียมคาร์บอเนต แอมโมเนีย (nh3) จึงไม่ใช่ voc เพราะไม่มีคาร์บอนในโมเลกุล ยืนยันว่าเหตุผลที่ถูกต้องคือไม่มีคาร์บอน ไม่ใช่ไม่มีทั้ง c และ h ตามที่เอกสารพิมพ์ไว้ \n fao นิยาม food loss ว่าเป็นการลดลงของปริมาณหรือคุณภาพอาหารจากการตัดสินใจและการกระทำของผู้จัดหาอาหารในห่วงโซ่ ตั้งแต่การเก็บเกี่ยว การฆ่า หรือการจับสัตว์น้ำ ไปจนถึงแต่ไม่รวมระดับค้าปลีก ส่วนที่เกิดที่ระดับค้าปลีก ผู้ให้บริการอาหาร และผู้บริโภค จัดเป็น food waste ตรงกับที่เอกสารแยกไว้ \n โคเป็นชนิดสัตว์ที่ปล่อยแก๊สเรือนกระจกมากที่สุดในภาคปศุสัตว์จริง โดยโคทั้งเนื้อและนมรวมกันปล่อยราว 3.8 กิกะตันคาร์บอนไดออกไซด์เทียบเท่าต่อปี คิดเป็นร้อยละ 62 ของทั้งภาคปศุสัตว์ ซึ่งภาคปศุสัตว์ทั้งหมดคิดเป็นราวร้อยละ 12 ของการปล่อยแก๊สเรือนกระจกจากกิจกรรมมนุษย์'],['one-health--oh-concept--กลยุทธ์ลดความเสี่ยงด้านสิ่งแวดล้อม','กลยุทธ์ลดความเสี่ยงด้านสิ่งแวดล้อม','กลยุทธ์ลดความเสี่ยงด้านสิ่งแวดล้อม \n เอกสารเน้นว่า ทุกกลยุทธ์มีความเสี่ยงที่จะไปกระทบความมั่นคงทางอาหารและรายได้เกษตรกร \n 1. agroecology strategy \n ใช้ feed additives เพื่อลด ghg \n breeding สัตว์ให้ทนโรคและลด methane \n วัคซีนและ biosecurity \n การจัดการปุ๋ย มูลสัตว์ และสารเคมี \n กฎหมายจำกัดการใช้ที่ดินและการปล่อยมลพิษ \n monitoring pollutants \n 2. diet change strategy \n 3. energy efficiency strategy \n ใช้ clean energy เช่น solar และ hydropower แต่มี ต้นทุนระยะสั้นสูงขึ้น \n ใช้ smart management system เช่น sensor เพื่อเพิ่มประสิทธิภาพของฟาร์ม \n การใช้ feed additive เพื่อลดแก๊สเรือนกระจกมีหลักฐานเชิงปริมาณรองรับ โดย 3-nitrooxypropanol ลดการปล่อยมีเทนจากการหมักในกระเพาะของโคนมได้ราวร้อยละ 32.7 ที่ขนาดเฉลี่ย 70.5 มิลลิกรัมต่อกิโลกรัมวัตถุแห้ง และประสิทธิภาพลดลงเมื่ออาหารมี ndf สูงขึ้น'],['one-health--oh-concept--รูปแบบข้อสอบของรุ่นก่อนหน้า','รูปแบบข้อสอบของรุ่นก่อนหน้า','รูปแบบข้อสอบของรุ่นก่อนหน้า \n ทั้งหัวข้อ gmo และหัวข้อสิ่งแวดล้อม ผู้สรุปบันทึกว่าออกเป็น ข้อถูกหรือผิดหัวข้อละ 10 ข้อ โดย gmo ออกเป็นภาษาอังกฤษ \n มีข้อที่ผู้สรุปจำได้ว่าถามว่า ถ้าตัดยีนออกจากสิ่งมีชีวิตแล้วใส่ชิ้นส่วนเดิมนั้นกลับคืนไป จะถือเป็น gmo หรือไม่ ผู้สรุปเองไม่แน่ใจในคำตอบและไม่ได้บันทึกคีย์ไว้ จึงยกมาเป็นประเด็นให้ไปถามผู้บรรยาย ไม่ควรจำคำตอบใดไปตอบ']],'one-health--oh-disease-prevention':[['one-health--oh-disease-prevention--emerging-zoonotic-disease-และ-tads','Emerging zoonotic disease และ TADs','emerging zoonotic disease และ tads \n emerging zoonotic diseases \n โรคที่ newly recognized หรือ newly evolved \n โรคที่มีอยู่เดิมแต่ increase in incidence หรือขยาย geographical, host หรือ vector range \n ก่อ serious human health and economic impacts \n transboundary animal diseases (tads) \n เป็นโรคระบาดที่ highly contagious \n แพร่เร็วโดยไม่สนใจพรมแดนประเทศ เอกสารยกตัวอย่าง african horse sickness (ahs) ที่เพิ่งระบาด \n ทำให้สัตว์ ตายและป่วยในอัตราสูง \n ก่อ serious socio-economic and public health consequences \n การทบทวนวรรณกรรมพบเชื้อก่อโรคในคน 1,415 ชนิด ในจำนวนนี้ 868 ชนิดหรือร้อยละ 61 เป็น zoonotic และในกลุ่มเชื้ออุบัติใหม่ 175 ชนิด มี 132 ชนิดหรือร้อยละ 75 ที่เป็น zoonotic ซึ่งสอดคล้องกับตัวเลขราวร้อยละ 60 และมากกว่าร้อยละ 75 ที่เอกสารเน้นคู่กัน \n african horse sickness ปรากฏในประเทศไทยเป็นครั้งแรกเมื่อวันที่ 17 มีนาคม 2020 และถูกมองว่าคุกคามอุตสาหกรรมม้าของภูมิภาคเอเชียตะวันออกเฉียงใต้ทั้งหมด สอดคล้องกับที่เอกสารยกเป็นตัวอย่างโรคข้ามพรมแดน'],['one-health--oh-disease-prevention--แนวทาง-one-health-ในการรับมือโรค-4-ข้อ','แนวทาง One Health ในการรับมือโรค 4 ข้อ','แนวทาง one health ในการรับมือโรค 4 ข้อ \n 1. surveillance and early detection \n monitor ทั้ง คน สัตว์ (ทั้งสัตว์ป่าและสัตว์เลี้ยง) และสิ่งแวดล้อม \n สร้าง early warning system เพื่อจับสัญญาณให้เร็ว \n 2. research and data sharing \n 3. risk assessment and mitigation \n ประเมินความเสี่ยงและดำเนินมาตรการเพื่อลดความเสี่ยง \n พัฒนาและปรับปรุงกฎระเบียบและมาตรการควบคุม \n เอกสารยกตัวอย่าง มาตรการกักโรคก่อนเข้าประเทศที่สนามบิน กรณี mers ซึ่งใช้เครื่องวัดอุณหภูมิคัดกรองผู้เดินทาง \n 4. collaboration ระหว่าง public health และ veterinary ทั้งในและต่างประเทศ \n คู่มือไตรภาคีของ who fao และ woah วางกรอบการรับมือโรคติดต่อระหว่างสัตว์และคนแบบหลายภาคส่วนไว้ตรงกับ 4 ข้อในเอกสารสรุป คือกลไกการประสานงานหลายภาคส่วน การประเมินความเสี่ยงร่วม การเฝ้าระวังและการแบ่งปันข้อมูล และการสอบสวนกับตอบโต้โรคแบบประสานกัน รวมถึงการพัฒนากำลังคนและการสื่อสารความเสี่ยง'],['one-health--oh-disease-prevention--กรณีศึกษา-ebola','กรณีศึกษา Ebola','กรณีศึกษา ebola \n สัตว์ที่เป็นแหล่งรังโรคหรือพาหะได้: ค้างคาวกินผลไม้ (fruit bat), ไพรเมตที่ไม่ใช่มนุษย์ (non-human primate) และสุกร \n เอกสารเล่าว่าจุดเริ่มมาจากลิงชิมแปนซีที่ถูกล่ามาชำแหละกินในหมู่บ้าน \n ปัจจัยที่ทำให้แพร่: ติดจากคนสู่คนได้ และตอนแรก ยังไม่รู้ว่าเชื้อติดต่อทางไหน \n who ประเมินว่าอาจกลายเป็น pandemic จึงนำแนวคิด one health มาช่วย \n สาเหตุที่ทำให้เกิดการระบาด \n ไม่มีการ monitor โรคในสัตว์ \n เมื่อรู้ว่ามีการระบาดแล้วก็ยัง จัดการไม่ถูกต้อง โดยเฉพาะการจัดการศพผู้เสียชีวิต \n ประชาชนขาดแหล่งอาหารที่มั่นคงและปลอดภัย จึงต้องพึ่งการล่าสัตว์ป่า \n response plans \n กักตัว คัดกรอง ให้เร็วและทันสมัย \n มาตรการจัดการศพผู้เสียชีวิต \n monitor โรคในสัตว์ป่า ตรวจหาเชื้อที่ circulating ในพื้นที่ รวมถึงการเก็บตัวอย่างอากาศและการจัดการซากสัตว์ \n ค้างคาวกินผลไม้เป็นแหล่งรังโรคของ ebola virus จริง โดยพบหลักฐานการติดเชื้อแบบไม่แสดงอาการในค้างคาวผลไม้ 3 ชนิดจากการเก็บตัวอย่างสัตว์มีกระดูกสันหลังขนาดเล็กกว่าหนึ่งพันตัวระหว่างการระบาดในคนและลิงใหญ่ที่กาบองและสาธารณรัฐคองโก \n การสัมผัสร่างและสารคัดหลั่งของผู้เสียชีวิตในพิธีศพเป็นเส้นทางการแพร่เชื้อ ebola จริง เพราะครอบครัวและชุมชนในแอฟริกาตะวันตกมักสัมผัสและอาบน้ำศพเพื่อเตรียมงานศพ จึงต้องมีมาตรฐานการฝังศพที่ปลอดภัยและสมศักดิ์ศรีเป็นมาตรการควบคุมโรค ตรงกับที่เอกสารเน้นเรื่องการจัดการศพผู้เสียชีวิต'],['one-health--oh-disease-prevention--กรณีศึกษา-covid-19-และไข้หวัดนก','กรณีศึกษา COVID-19 และไข้หวัดนก','กรณีศึกษา covid-19 และไข้หวัดนก \n covid-19 \n คนกลัวสุนัขและแมวเพราะกลัวแพร่เชื้อ เกิดคำถามว่า ถ้าเจ้าของติดเชื้อแล้วใครจะดูแลสัตว์เลี้ยง \n มีความเห็นไม่ตรงกันระหว่างกรมปศุสัตว์และกรมควบคุมโรค \n หน่วยสัตวแพทย์ของจุฬาฯ (eidas) ต้องลงพื้นที่ไปเก็บตัวอย่างสัตว์เพื่อ monitor และให้คำแนะนำประชาชนในพื้นที่ \n avian influenza \n เอกสารมองว่าไข้หวัดนกน่ากลัวกว่า พาหะสำคัญคือ เป็ดและไก่ที่เลี้ยงหลังบ้านหรือไล่ทุ่ง \n ตลาดค้าสัตว์ปีกมีชีวิต เช่น คลองเตย เยาวราช เป็นจุดเสี่ยง เพราะชำแหละขายกันหลังร้าน \n เสี่ยงเพราะ สัตว์มาจากหลายแหล่งมารวมกัน โดยไม่มีการจัดการที่ดี \n ความกังวลเรื่องสัตว์เลี้ยงกับ sars-cov-2 มีน้ำหนักไม่เท่ากันระหว่างสองชนิด การทดลองพบว่าไวรัสเพิ่มจำนวนได้ไม่ดีในสุนัข สุกร ไก่ และเป็ด แต่แมวติดเชื้อได้และยังติดต่อระหว่างแมวผ่านทางอากาศได้ด้วย \n ตลาดค้าสัตว์ปีกมีชีวิตเป็นจุดเสี่ยงต่อการติดเชื้อไข้หวัดนก h5n1 ในคนจริง การศึกษาแบบ case-control พบว่าการไปตลาดสัตว์ปีกสดเป็นปัจจัยเสี่ยงอิสระ (or 15.4) และผู้ป่วยในเขตชนบทมักสัมผัสสัตว์ปีกหลังบ้านที่ป่วยหรือตาย \n เป็ดไล่ทุ่งมีบทบาทสำคัญต่อการเกิดและการแพร่ของไข้หวัดนกชนิดรุนแรงในประเทศไทยจริง โดยการวิเคราะห์เชิงพื้นที่พบว่าจำนวนเป็ดไล่ทุ่งสัมพันธ์อย่างมากกับความเข้มข้นของการปลูกข้าวและช่วงเก็บเกี่ยวข้าวนาปรัง'],['one-health--oh-disease-prevention--รูปแบบข้อสอบของรุ่นก่อนหน้า','รูปแบบข้อสอบของรุ่นก่อนหน้า','รูปแบบข้อสอบของรุ่นก่อนหน้า \n ผู้สรุปบันทึกไว้ว่าหัวข้อนี้ของรุ่นก่อนหน้าออกเป็น ข้อถูกหรือผิด 17 ข้อ และค่อนข้างตรงไปตรงมา ส่วน ebola ที่เล่าไว้ยาวกลับไม่ได้ออก ให้ใช้เป็นแนวทางเท่านั้น เพราะการบรรยายและข้อสอบของปีนี้อาจเปลี่ยนไป']],'one-health--oh-foodborne':[['one-health--oh-foodborne--ภาพรวมและจุดปนเปื้อนตลอดห่วงโซ่','ภาพรวมและจุดปนเปื้อนตลอดห่วงโซ่','ภาพรวมและจุดปนเปื้อนตลอดห่วงโซ่ \n one health approach ทำอะไรได้บ้างใน food safety \n การเฝ้าระวังโรค เชื้อพบได้ตั้งแต่ก่อนเข้าวงจรการผลิต เช่น ตรวจไก่ที่ปนเปื้อน salmonella \n การประเมินความเสี่ยงและการแชร์ข้อมูล ระหว่างสาธารณสุขกับปศุสัตว์ \n มาตรการควบคุมและป้องกันโรค เช่น biosecurity และการจัดการสุขาภิบาล \n climate change ทำให้สัตว์พาหะเพิ่มขึ้นและสารพิษจากเชื้อราเพิ่มขึ้น \n objectives \n to control, prevent, reduce foodborne diseases \n to ensure food security \n to safeguard public health and environmental quality \n การเปลี่ยนแปลงสภาพภูมิอากาศทำให้สารพิษจากเชื้อราเพิ่มขึ้นจริง แบบจำลองคาดว่า aflatoxin b1 จะกลายเป็นปัญหาความปลอดภัยอาหารในข้าวโพดของยุโรป โดยเฉพาะภายใต้ฉากทัศน์อุณหภูมิเพิ่มขึ้น 2 องศาเซลเซียส ซึ่งเป็นฉากทัศน์ที่มีโอกาสเกิดมากที่สุด'],['one-health--oh-foodborne--norovirus-ปนเปื้อนในราสป์เบอร์รี','Norovirus ปนเปื้อนในราสป์เบอร์รี','norovirus ปนเปื้อนในราสป์เบอร์รี \n ในขั้นตอนการผลิตไม่ได้ล้างผล ทำเพียงแช่น้ำ \n ตอนแช่แข็งจะเอาเบอร์รีจากทุกสวนมาผสมกัน ถ้าสวนใดสวนหนึ่งปนเปื้อนก็กระจายไปทุกล็อต \n น้ำที่ใช้รดปนเปื้อน และมือคนเก็บ เป็นแหล่งของเชื้อโดยตรง \n ปัจจุบันพบ norovirus genogroup ii (nov gii) ในสัตว์เช่นเดียวกับที่พบในคน จึงต้องเฝ้าระวังไว้ \n เอกสารเขียนเพียงว่าพบ nov gii ในสัตว์ โดยไม่ระบุชนิดสัตว์ จึงไม่ควรเติมชนิดสัตว์เองในการตอบ \n การเฝ้าระวังตลอดห่วงโซ่การผลิตเบอร์รีในยุโรปยืนยันว่าน้ำที่ใช้ในแปลงและมือของคนเก็บเป็นช่องทางเข้าของไวรัสในทางเดินอาหารจากคน โดยพบ human adenovirus ในน้ำชลประทานร้อยละ 9.5 มือคนทำงานร้อยละ 5.8 และห้องน้ำในฟาร์มร้อยละ 9.1 และตรวจพบ norovirus gii ในตัวอย่างน้ำที่แปลงปลูกด้วย \n มีการตรวจพบ norovirus genogroup ii ในสัตว์จริง โดยการตรวจอุจจาระในนิวซีแลนด์พบ norovirus ในสุกร 2 จาก 23 ตัวอย่าง คิดเป็นร้อยละ 9 และทั้งหมดเป็น genogroup ii ส่วนในแกะที่พบร้อยละ 24 นั้นเป็น genogroup iii ทั้งหมด ดังนั้นชนิดสัตว์ที่ตรงกับ nov gii ในรายงานนี้คือสุกร ไม่ใช่แกะ'],['one-health--oh-foodborne--shiga-toxin-producing-e-coli-ในถั่วงอก','Shiga toxin-producing E. coli ในถั่วงอก','shiga toxin-producing e. coli ในถั่วงอก \n ปกติ stec มี โคเป็น reservoir หลัก \n แต่เคสนี้ต่างออกไป คือ สัตว์ไม่ได้เป็นพาหะ คนเป็นผู้ทำให้เกิดการปนเปื้อน \n เชื้อที่ก่อโรคไม่ได้อยู่ในกลุ่ม enterohemorrhagic แต่เป็นกลุ่ม enteroaggregative สายพันธุ์ o104:h4 ที่ได้รับ virulence gene จนสร้าง shiga toxin ได้ \n การระบาดในเยอรมนีปี 2011 มีถั่วงอกเป็นพาหะที่เป็นไปได้มากที่สุด และเชื้อสาเหตุถูกจัดชนิดเป็น enteroaggregative shiga-toxin-producing e. coli o104:h4 ที่สร้าง extended-spectrum beta-lactamase ด้วย ยืนยันว่าเชื้อไม่ได้อยู่ในกลุ่ม enterohemorrhagic แบบดั้งเดิม'],['one-health--oh-foodborne--bse-prion-protein-ในเนื้อ','BSE prion protein ในเนื้อ','bse prion protein ในเนื้อ \n วิธีป้องกันที่ดีที่สุดคือทำ active surveillance เพราะวัวที่ติดเชื้อไม่แสดงอาการ \n ทำโดย ตรวจสมองและไขสันหลังเพื่อหารอยโรคในวัวที่เข้าโรงเชือด \n การปรุงสุกไม่ช่วยลดการปนเปื้อน \n ผู้สรุปทำเครื่องหมายไว้ว่าหัวข้อ bse ไม่ได้ออกในข้อสอบของรุ่นก่อนหน้า แต่กลไกที่ว่า prion ทนความร้อนยังเป็นเนื้อหาที่ต้องเข้าใจ \n เชื้อ bse ทนความร้อนสูงมาก แม้ใช้กระบวนการ rendering ที่ 133 องศาเซลเซียส นาน 20 นาทีภายใต้ความดันตามข้อกำหนดของสหภาพยุโรป ก็ลดปริมาณเชื้อได้เพียงราว 2 ถึง 3 log และยังตรวจพบเชื้อหลงเหลืออยู่ อีกทั้ง bse ทนความร้อนมากกว่าเชื้อ scrapie อย่างสม่ำเสมอ จึงยืนยันว่าการปรุงสุกตามปกติไม่สามารถกำจัดการปนเปื้อนได้'],['one-health--oh-foodborne--listeria-monocytogenes-ในอาหารพร้อมบริโภค','Listeria monocytogenes ในอาหารพร้อมบริโภค','listeria monocytogenes ในอาหารพร้อมบริโภค \n เจริญได้ที่ ph กว้าง ทนความเข้มข้นเกลือสูง และโตที่อุณหภูมิตู้เย็น \n เชื้ออยู่ได้ทั้งในคน สัตว์ และสิ่งแวดล้อม ชอบที่เย็น ความชื้นสูง ตามพื้นและอุปกรณ์ เช่น เครื่องหั่นเนื้อ จึงปนเปื้อนได้ทุก process ในโรงงาน \n พบบ่อยในอาหารแช่เย็นและ ready-to-eat food \n มีข้อกำหนด ห้ามตรวจพบเชื้อในอาหารโดยเด็ดขาด \n ควบคุมด้วยการ swab หาเชื้อตามอุปกรณ์และไลน์การผลิตเป็นรูทีน \n คนปกติเป็นพาหะโดยไม่แสดงอาการได้ \n l. monocytogenes ทนเกลือสูงและสภาพเป็นกรด เจริญได้ที่อุณหภูมิตู้เย็นและในภาวะออกซิเจนต่ำ และอยู่รอดได้นานทั้งในสิ่งแวดล้อม บนอาหาร ในโรงงานแปรรูป และในตู้เย็นที่บ้าน โรคจึงมักผูกกับ ready-to-eat refrigerated food ที่ปนเปื้อนซ้ำหลังผ่านกระบวนการฆ่าเชื้อ \n คนปกติเป็นพาหะของเชื้อได้โดยไม่แสดงอาการ โดยเชื้อเป็น transitory resident ของลำไส้ และประชากรทั่วไปราว 2 ถึง 10 เปอร์เซ็นต์เป็นพาหะโดยไม่มีผลต่อสุขภาพที่สังเกตได้ \n การควบคุมใช้ environmental monitoring program ในพื้นที่ผลิต โดยเก็บตัวอย่างทั้งพื้นผิวสัมผัสอาหารและพื้นผิวที่ไม่สัมผัสอาหาร และเลือกอุปกรณ์เก็บให้เหมาะกับพื้นผิว เช่น ใช้ฟองน้ำกับพื้นผิวเรียบกว้าง และใช้ swab กับรอยแตกรอยแยก \n อุปกรณ์ในไลน์การผลิตเป็นแหล่งกักเชื้อที่ทำให้ปนเปื้อนซ้ำได้จริง ในโรงงานแซลมอนรมควันที่เชื่อมโยงกับการระบาดสองครั้ง เครื่องลอกหนังเป็นแหล่งปนเปื้อนหลัก เชื้อสายพันธุ์ก่อโรคฝังตัวอยู่ในสายพานสองเส้นและลูกกลิ้ง และการล้างและฆ่าเชื้ออย่างเข้มข้นยังเอาไม่ออก ต้องเปลี่ยนเครื่องจึงหยุดได้'],['one-health--oh-foodborne--รูปแบบข้อสอบของรุ่นก่อนหน้า','รูปแบบข้อสอบของรุ่นก่อนหน้า','รูปแบบข้อสอบของรุ่นก่อนหน้า \n ผู้สรุปบันทึกว่าหัวข้อนี้ออกเป็นข้อเติมคำ โดยให้ระบุว่า เหตุการณ์ปนเปื้อนแต่ละกรณีมาจากสัตว์ คน หรือสิ่งแวดล้อม จึงควรจำแหล่งปนเปื้อนของทั้ง 4 กรณีให้ได้ ทั้งนี้ข้อสอบปีนี้อาจเปลี่ยนรูปแบบ']],'one-health--oh-global-network':[['one-health--oh-global-network--ภาพรวม-นิยาม-และ-one-health-triad','ภาพรวม นิยาม และ One Health triad','ภาพรวม นิยาม และ one health triad \n ทำไมเรื่องนี้สำคัญ (why this matters) \n 75% ของ emerging infectious diseases มีต้นกำเนิดเป็น zoonotic \n การเปลี่ยนแปลงของ climate, land-use และ biodiversity เป็นตัวขับเคลื่อนความเสี่ยงโรคใหม่ \n การตอบสนองที่ได้ผลต้องอาศัย vets, physicians, ecologists และ policymakers ทำงานเป็นทีมเดียวกัน \n นิยามที่ใช้ในเลกเชอร์นี้ \n one health approach = กรอบการทำงานแบบบูรณาการและร่วมมือกัน (integrated, collaborative framework) ที่เชื่อมสุขภาพคน สัตว์ และสิ่งแวดล้อมเข้าด้วยกัน \n one health triad = 3 domains ที่เชื่อมถึงกัน ได้แก่ animal health, human health, environmental health โดยมี shared health outcome ร่วมกันหนึ่งเดียว \n แนวคิดหลักที่พิมพ์บนสไลด์ โรค เชื้อก่อโรค และ environmental stressors เคลื่อนที่ข้าม species และข้าม ecosystem ได้อย่างอิสระ ดังนั้นวิธีแก้ปัญหาสุขภาพก็ต้องข้ามขอบเขตตามไปด้วย \n 6 learning objectives \n apply systems thinking \n build collaborative networks \n investigate real cases \n communicate across disciplines \n design interventions \n evaluate outcomes \n ในบรรดา pathogen ที่ก่อโรคในคนซึ่งจัดว่าเป็น emerging จำนวน 175 ชนิด มี 132 ชนิด (75%) ที่เป็น zoonotic และโดยรวม zoonotic pathogens มีโอกาสสัมพันธ์กับ emerging disease มากกว่า non-zoonotic pathogens ประมาณ 2 เท่า'],['one-health--oh-global-network--โครงสร้างเครือข่าย-บทบาทผู้เข้าร่วม-และ-reporting-protocol','โครงสร้างเครือข่าย บทบาทผู้เข้าร่วม และ reporting protocol','โครงสร้างเครือข่าย บทบาทผู้เข้าร่วม และ reporting protocol \n โครงสร้างเครือข่าย \n ศูนย์กลางคือ global coordination hub เชื่อมกับ 6 nodes ได้แก่ africa node, asia-pacific node, americas node, europe node, middle east node และ your class node \n แต่ละ node แทนสถาบันที่เป็น partner หนึ่งแห่ง \n 4 บทบาทของผู้เข้าร่วม \n field veterinarian เฝ้าระวังประชากรสัตว์ เก็บตัวอย่าง รายงาน morbidity และ mortality ที่ผิดปกติ \n public health liaison ติดตามข้อมูลผู้ป่วยในคน และประสานกับ clinical health services \n environmental analyst ประเมินปัจจัยด้าน habitat, climate และ ecosystem ที่มีผลต่อการอุบัติของโรค \n communications lead เรียบเรียงผลการสอบสวนเป็น brief สำหรับ policymakers และประชาชน \n บทบาทหมุนเวียนทุก 2 สัปดาห์ เพื่อให้นิสิตได้ผ่านครบทั้ง 4 มุมมอง \n scenario 1 กรณี wetland reservoir \n โคตาย 12 ตัว ภายใน 10 วัน ใกล้พื้นที่ชุ่มน้ำที่ได้รับการคุ้มครอง \n ผู้ป่วยคน 2 ราย มีอาการไข้ลักษณะคล้ายกัน \n พบกิจกรรมของนกอพยพเพิ่มขึ้นหลังน้ำท่วมตามฤดูกาล \n node ต้องสอบสวนและรายงานผลภายใน 48 ชั่วโมง \n 5 ขั้นตอนของการสื่อสารและรายงาน \n 1. detect node ในพื้นที่พบความผิดปกติจากรายงานภาคสนามหรือรายงานทางคลินิก \n 2. report ส่ง standardized case form ไปยัง regional hub \n 3. share hub กระจาย alert ไปยัง nodes ที่เกี่ยวข้อง \n 4. convene ทีมสหสาขาประชุมทบทวนร่วมกัน \n 5. respond ออกข้อเสนอแนะแบบประสานงานไปยัง stakeholders \n ลำดับ detect ไป report ไป share ไป convene ไป respond เป็นลำดับที่สไลด์พิมพ์เลขกำกับไว้ชัดเจน ข้อสอบชอบสลับขั้น share กับ convene ให้จำว่าต้องกระจายข่าวก่อนจึงจะเรียกประชุมทีมได้ \n การซ้อมแผนรับมือ outbreak แบบข้ามภาคส่วน (one health simulation exercise) ที่ให้ผู้เข้าร่วมสวมบทบาทของภาค public health, animal health และ food safety เป็นวิธีที่ใช้จริงในการฝึกและประเมินขีดความสามารถของเครือข่าย one health โดยการซ้อมระดับชาติใน 11 ประเทศยุโรป (ผู้เข้าร่วม 255 คน ปี 2022) สรุปข้อเสนอแนะร่วมกันว่าต้องตั้ง formal communication channels ระหว่างภาคส่วน และมี common data sharing platform \n ในระบบจริง ประเทศสมาชิก woah มีพันธะต้องแจ้งเหตุการณ์โรคที่อยู่ในบัญชี (listed diseases) และโรคอุบัติใหม่ต่อ woah ผ่านระบบ wahis โดยการแจ้งครั้งแรก (immediate notification) ต้องทำภายใน 24 ชั่วโมงนับจากที่ยืนยันเหตุการณ์ ซึ่งเป็นคนละกรอบเวลากับ 48 ชั่วโมงที่สไลด์กำหนดไว้สำหรับกิจกรรมในชั้นเรียน'],['one-health--oh-global-network--module-2-surveillance-dashboard-และโรคสัตว์สู่คนที่จัดลำดับความส','Module 2 — surveillance dashboard และโรคสัตว์สู่คนที่จัดลำดับความสำคัญ','module 2 — surveillance dashboard และโรคสัตว์สู่คนที่จัดลำดับความสำคัญ \n ค่าบน dashboard รายงานสัตว์ป่วยรายสัปดาห์ของ regional node \n wk1 = 4, wk2 = 7, wk3 = 12, wk4 = 9, wk5 = 15, wk6 = 11 \n สไลด์ตั้งคำถามว่าอะไรทำให้เกิด spike ที่ week 3 แต่ค่าที่สูงที่สุดในกราฟจริงคือ week 5 ที่ 15 ระวังอย่าสลับสองตัวนี้กัน \n การอ่าน dashboard ต้องทำ 3 อย่าง \n ระบุ spike ที่อาจบ่งชี้การอุบัติของ outbreak \n เปรียบเทียบข้อมูลข้าม 3 ชั้น คือชั้นสัตว์ ชั้นคน และชั้นสิ่งแวดล้อม \n แจ้ง anomaly ไปยัง nodes อื่นเพื่อ cross-check \n 4 โรคสัตว์สู่คนที่ถูก spotlight พร้อมจุดจับในการควบคุมและเฝ้าระวัง \n avian influenza เฝ้าระวังในนกป่าและสัตว์ปีก มีความเสี่ยง spillover สู่คน \n rabies รณรงค์ฉีดวัคซีนข้ามพรมแดน และจัดการประชากรสุนัข \n brucellosis คัดกรองในปศุสัตว์ เชื่อมโยงกับการสัมผัสเชิงอาชีพในคน \n leptospirosis สัตว์ฟันแทะเป็น reservoir และมีเส้นทางการติดต่อสัมพันธ์กับน้ำท่วม \n leptospirosis: หนูเป็น reservoir ที่ปล่อยเชื้อออกมาทางปัสสาวะปนเปื้อนสิ่งแวดล้อม คนจึงติดเชื้อจากการสัมผัสสิ่งแวดล้อมที่ปนเปื้อน และเหตุการณ์น้ำท่วมบ่อยครั้งอาจช่วยกระจายเชื้อในพื้นที่ต่ำ ทำให้เส้นทางการติดต่อสัมพันธ์กับทั้งความชุกของหนูและน้ำท่วม'],['one-health--oh-global-network--module-3-regional-case-studies-และ-cross-node-simulation','Module 3 — regional case studies และ cross-node simulation','module 3 — regional case studies และ cross-node simulation \n จับคู่โรคกับ node ให้ได้ (ออกสอบง่ายมาก) \n africa node = rift valley fever outbreak เชื่อมโยงกับการค้าปศุสัตว์และรูปแบบปริมาณฝน \n asia-pacific node = avian influenza แพร่ผ่าน live bird markets และเส้นทางนกอพยพ \n americas node = amr ในฟาร์มโคนม ส่งผลต่อชุมชนใกล้เคียง \n europe node = tick-borne disease ขยายพื้นที่การระบาดตามภาวะโลกร้อน \n middle east node = การเฝ้าระวัง mers-cov ในประชากรอูฐ \n รูปแบบ cross-node outbreak simulation \n ทีมละ 4 คน แต่ละคนแทน node คนละภูมิภาค \n ต้องร่าง one health response plan ที่ครอบคลุมปัจจัยด้านสัตว์ คน และสิ่งแวดล้อม ภายใน 30 นาที \n การจัดสรรเวลา briefing 10 นาที, investigation and planning 30 นาที, cross-node presentation 15 นาที, facilitated debrief 15 นาที \n africa node: การระบาดของ rift valley fever สัมพันธ์กับรูปแบบปริมาณฝน โดยการระบาดของ rvf ในแอฟริกาตะวันออกที่ทราบทั้งหมดในช่วงปี 1950 ถึงพฤษภาคม 1998 เกิดตามหลังช่วงที่ฝนตกสูงผิดปกติ และการพยากรณ์ล่วงหน้าอาจทำได้ถึงประมาณ 5 เดือนก่อนการระบาด \n middle east node: อูฐ dromedary เป็นประชากรสัตว์ที่ติดเชื้อ mers-cov จริง จึงเป็นเป้าของการเฝ้าระวัง โดยซีรัมอูฐจากโอมาน 50 จาก 50 ตัว (100%) และจากสเปน 15 จาก 105 ตัว (14%) ตรวจพบ antibody ต่อ mers-cov spike ขณะที่ซีรัมของแกะ แพะ โค และ camelid ชนิดอื่นในยุโรปตรวจไม่พบ'],['one-health--oh-global-network--module-4-5-stakeholders-policy-briefing-จริยธรรม-และ-digital-too','Module 4-5 — stakeholders, policy briefing, จริยธรรม และ digital tools','module 4-5 — stakeholders, policy briefing, จริยธรรม และ digital tools \n 6 กลุ่ม stakeholder ที่ต้องดึงเข้ามามีส่วนร่วม \n ministries of health \n veterinary authorities \n environmental agencies \n local communities \n research institutions \n media and public communication \n policy briefing role-play \n สถานการณ์คือรัฐมนตรีเกษตรมีเวลา 10 นาที ก่อนแถลงข่าว \n หลักการ briefing 3 ข้อ คือ lead with impact (พูดความเสี่ยงต่อคนและต่อการทำมาหากินก่อน), avoid jargon และ be action-oriented \n ปิดท้ายด้วยข้อเสนอแนะที่ชัดเจนและทำได้จริง 2 ถึง 3 ข้อ \n 4 ประเด็นด้านจริยธรรมและวัฒนธรรมในเครือข่ายสุขภาพระดับโลก \n cultural sensitivity เคารพวิถีปฏิบัติ การทำมาหากิน และความเชื่อของท้องถิ่น \n equitable data sharing ทุก node มีเสียงและเข้าถึงข้อมูลร่วมได้ ไม่ว่าจะมีทรัพยากรมากหรือน้อย \n avoiding harm คำนึงถึงผลกระทบที่ไม่ได้ตั้งใจของมาตรการ เช่น การ culling และการจำกัดการเดินทาง \n informed consent การเก็บข้อมูลภาคสนามจากชุมชนและเกษตรกรต้องโปร่งใสและเป็นไปโดยสมัครใจ \n 4 digital tools ที่หนุนการทำงานของเครือข่าย \n gis mapping platforms แสดงการกระจายเชิงพื้นที่ตรงรอยต่อสัตว์ คน สิ่งแวดล้อม \n shared dashboards รายงานเคสแบบ real-time และดูแนวโน้ม \n discussion forums ทำงานร่วมกันข้าม node แบบ asynchronous \n lab information systems ติดตามการส่งตัวอย่างและผลวินิจฉัยข้ามสถาบัน'],['one-health--oh-global-network--module-6-peer-review-และตาราง-cdc-priority-zoonoses','Module 6 — peer review และตาราง CDC priority zoonoses','module 6 — peer review และตาราง cdc priority zoonoses \n 5 เกณฑ์ในการทำ cross-node peer review \n scientific accuracy การวินิจฉัยและการประเมินความเสี่ยงอิงหลักฐานหรือไม่ \n cross-sector integration แผนครอบคลุมครบทั้ง 3 domains ของ one health หรือไม่ \n feasibility ข้อเสนอแนะทำได้จริงในระดับพื้นที่หรือไม่ \n communication clarity ผู้ที่ไม่ใช่ผู้เชี่ยวชาญเข้าใจได้หรือไม่ \n ethical soundness มีการคำนึงถึงมิติวัฒนธรรมและความเป็นธรรมหรือไม่ \n รูป cdc "priority zoonoses around the globe" \n โรคสัตว์สู่คนที่ถูกจัดเป็นลำดับความสำคัญบ่อยที่สุดทั่วโลก ได้แก่ rabies (24 จาก 25 workshops ที่จัดมา), zoonotic influenzas, viral hemorrhagic fevers, anthrax และ brucellosis \n แหล่งอ้างอิงที่พิมพ์บนรูปคือ cdc.gov/onehealth/global-activities/prioritization.html \n ถ้าโจทย์ถามว่าโรคใดถูกจัดลำดับความสำคัญบ่อยที่สุดในเวที prioritization ทั่วโลก ตอบ rabies และจำตัวเลข 24 of 25 workshops ไว้เป็นตัวยึด \n ใน one health zoonotic disease prioritization (ohzdp) process ของ us cdc โรคที่ถูกจัดเป็นลำดับความสำคัญบ่อยที่สุดทั่วโลกคือ rabies ซึ่ง cdc ระบุว่าถูกจัดลำดับใน 24 จาก 25 workshops ณ เวลาที่รายงาน ร่วมกับ zoonotic influenzas, viral hemorrhagic fevers, anthrax และ brucellosis'],['one-health--oh-global-network--การประเมินผลและตารางกิจกรรม-6-สัปดาห์','การประเมินผลและตารางกิจกรรม 6 สัปดาห์','การประเมินผลและตารางกิจกรรม 6 สัปดาห์ \n สัดส่วนคะแนน \n case investigation report 30% เป็นงานเขียนวิเคราะห์รายบุคคลจาก scenario ของ node ตัวเอง \n cross-node response plan 30% เป็นแผนกลุ่มที่ต้องครอบคลุมทุก domain ของ one health \n policy briefing presentation 20% ประเมินจากความชัดเจนและความเป็นไปได้ของ role-play \n peer review and participation 20% \n ตารางกิจกรรม 6 สัปดาห์ \n wk1 orientation และ node assignment \n wk2 ปล่อย case scenario และเริ่มสอบสวน \n wk3 data sharing และวิเคราะห์ dashboard \n wk4 cross-node simulation exercise \n wk5 stakeholder role-play briefings \n wk6 peer review และ reflection \n ส่วนนี้เป็นกลไกของกิจกรรมในรายวิชา ไม่ใช่เนื้อหาวิชาการ อ่านไว้พอให้ทำกิจกรรมถูกและกันข้อที่ถามตรงตัวเลข ไม่ต้องลงแรงเท่าส่วนโรคและ quadripartite'],['one-health--oh-global-network--background-quadripartite-และกรอบ-one-health-ระดับโลก','Background — Quadripartite และกรอบ One Health ระดับโลก','background — quadripartite และกรอบ one health ระดับโลก \n องค์กรและ remit ที่สไลด์พิมพ์ไว้ \n quadripartite ประกอบด้วย 4 องค์กร คือ who, woah, fao และ unep และมี joint plan of action เป็นฐานของวาระ one health ระดับโลกที่อ้างถึงตลอดรายวิชานี้ (บรรทัดนี้พิมพ์ซ้ำอยู่ท้ายทุกสไลด์ในหมวดนี้) \n woah = world organisation for animal health, remit คือมาตรฐานและการรายงานโรคสัตว์ \n who = world health organization, remit คือแนวทางด้านสุขภาพคนและการประสาน international health regulations (ihr) \n unep = un environment programme, remit คือปัจจัยด้านสิ่งแวดล้อมที่ทำให้เกิดการอุบัติของโรค \n fao = food and agriculture organization, remit คือระบบอาหารและสุขภาพภาคเกษตร \n จาก screenshot เว็บไซต์ woah บนสไลด์ \n woah อธิบาย one health ว่าเป็นแนวคิดที่รู้จักกันมา มากกว่าหนึ่งศตวรรษ โดยสุขภาพคน สัตว์ และพืช พึ่งพากันและผูกกับสุขภาพของ ecosystems ที่สิ่งเหล่านั้นดำรงอยู่ \n wahis (world animal health information system) ถูกระบุว่าเป็น global reference platform สำหรับเผยแพร่ข้อมูลทางการของโรคที่มีความสำคัญทางระบาดวิทยาในสัตว์เลี้ยงและสัตว์ป่า \n สไลด์ชุดนี้ให้แค่ชื่อองค์กรกับ remit เท่านั้น ไม่มีการพิมพ์ปีก่อตั้ง ไม่มีวันที่ unep เข้าร่วมจนเปลี่ยน tripartite เป็น quadripartite และไม่มีช่วงปีของ joint plan of action อยู่ในเลกเชอร์นี้เลย อย่าเดาปีเอง \n quadripartite ประกอบด้วย 4 องค์กร คือ fao, unep, who และ woah ซึ่งร่วมกันจัดทำ one health joint plan of action เป็นกรอบวาระ one health ระดับโลก'],['one-health--oh-global-network--ตัวอย่างจริง-อุปสรรคที่พบบ่อย-และ-key-takeaways','ตัวอย่างจริง อุปสรรคที่พบบ่อย และ key takeaways','ตัวอย่างจริง อุปสรรคที่พบบ่อย และ key takeaways \n 3 ตัวอย่างเครือข่าย one health ที่ทำงานได้จริง \n rabies-free regions การรณรงค์ฉีดวัคซีนสุนัขจำนวนมากแบบประสานงานกัน ทำให้หลายประเทศไม่มีผู้เสียชีวิตจากพิษสุนัขบ้าอีก \n wetland outbreak response การเฝ้าระวังร่วมด้านสัตว์และสิ่งแวดล้อมทำให้ตรวจพบ rift valley fever outbreak ได้แต่เนิ่น \n cross-border amr surveillance เครือข่ายห้องปฏิบัติการที่ใช้ร่วมกันติดตาม amr ข้ามระบบปศุสัตว์และระบบสุขภาพคน \n 4 อุปสรรคของเครือข่ายและวิธีแก้ที่สไลด์ให้ไว้ \n ข้อมูลขัดแย้งกันระหว่าง node แก้โดยอภิปรายความต่างอย่างเปิดเผย บันทึกสมมติฐานและความต่างของ methodology \n ความต่างของ time zone และการนัดหมาย แก้โดยอัปเดตผ่าน forum แบบ asynchronous และหมุนเวียนเวลาประชุมแบบ synchronous ให้เป็นธรรม \n กำแพงศัพท์เฉพาะทาง แก้โดยทำ shared glossary และถามให้กระจ่างตั้งแต่เนิ่น \n เห็นไม่ตรงกันเรื่องข้อเสนอแนะ แก้โดยจัด structured debate เสนอหลักฐานของแต่ละทางเลือกก่อนตัดสินใจ \n 4 key takeaways \n health is interconnected สุขภาพสัตว์ คน และสิ่งแวดล้อม จัดการแยกส่วนไม่ได้ \n collaboration is a skill การสื่อสารข้ามสาขาเป็นทักษะที่ต้องฝึก ไม่ใช่สิ่งที่เกิดขึ้นเอง \n data drives decisions การเฝ้าระวังที่แบ่งปันข้อมูลกันทำให้ตอบสนองได้เร็วขึ้นและมีข้อมูลรองรับมากขึ้น \n equity matters ทางออกที่ยั่งยืนต้องอาศัยการมีส่วนร่วมอย่างเป็นธรรมของ partner ทุกรายในเครือข่าย \n การฉีดวัคซีนสุนัขจำนวนมากลดการตายจากพิษสุนัขบ้าในคนได้จริง จากข้อมูลรายปี 1995-2005 ของ 7 ประเทศละตินอเมริกา ประเมินว่าการเพิ่มการฉีดวัคซีนสุนัข 10% ทำให้เคสพิษสุนัขบ้าในสุนัขลดลง 2.3% และทำให้ผู้เสียชีวิตในคนลดลงราว 12.4% แต่ประสิทธิผลส่วนเพิ่มจะลดลงเมื่ออุบัติการณ์ในสุนัขต่ำลง \n การเฝ้าระวังเชิงกลุ่มอาการในปศุสัตว์ที่ผูกกับสัญญาณสิ่งแวดล้อม (คำเตือนฝน el nino ปี 2015-2016) ใช้เป็นระบบเตือนภัยล่วงหน้าของ rift valley fever ได้จริง โดยกรมปศุสัตว์เคนยาเฝ้าระวัง 22 จังหวัดเสี่ยงสูงนาน 14 สัปดาห์ พบ 69 ฝูงเข้านิยามสงสัย และ 24 ฝูงเข้านิยาม probable แต่ไม่มีฝูงใดยืนยันผลทางห้องปฏิบัติการ \n ข้อมูลดาวเทียมด้านอุณหภูมิผิวน้ำทะเล ปริมาณฝน และดัชนีพืชพรรณ ถูกใช้พยากรณ์พื้นที่เสี่ยงการระบาดของ rift valley fever ล่วงหน้า 2-4 เดือน ในแอฟริกาตะวันออก ซูดาน และแอฟริกาตอนใต้ ช่วงปี 2006-2008 และคำพยากรณ์ได้รับการยืนยันด้วยการสำรวจกีฏวิทยาภาคสนามและรายงานเคสจริงในคนและปศุสัตว์'],['one-health--oh-global-network--หน่วยงานที่เอกสารระบุ','หน่วยงานที่เอกสารระบุ','หน่วยงานที่เอกสารระบุ \n us-cdc, seaohun, thohun สนับสนุนทุน จัดอบรม และทำงานวิจัยด้าน one health \n woah กำหนดมาตรฐานสุขภาพสัตว์ระดับโลก \n moph-tuc คือความร่วมมือระหว่างกระทรวงสาธารณสุขของไทยกับ us-cdc \n ศูนย์ one health ของกรมควบคุมโรค ทำหน้าที่บูรณาการข้อมูลคน สัตว์ และสิ่งแวดล้อม \n cu research cluster one health เป็นเครือข่ายวิจัยระดับมหาวิทยาลัย \n องค์กรที่เกี่ยวกับความปลอดภัยอาหารโดยตรง คือ codex alimentarius commission (cac) ซึ่งจัดทำมาตรฐานสากลภายใต้ sps agreement ดูรายละเอียดในหัวข้อ risk analysis \n ความตกลง sps ขององค์การการค้าโลกกำหนดให้ codex alimentarius commission เป็นองค์กรอ้างอิงสำหรับมาตรฐานความปลอดภัยอาหาร และให้ woah ซึ่งเดิมคือ international office of epizootics เป็นองค์กรอ้างอิงสำหรับมาตรฐานสุขภาพสัตว์และโรคติดต่อจากสัตว์สู่คน \n มาตรฐานของ codex และ woah มีน้ำหนักทางกฎหมายการค้า เพราะมาตรการสุขอนามัยที่สอดคล้องกับมาตรฐานสากลเหล่านี้ถือว่าจำเป็นต่อการคุ้มครองชีวิตและสุขภาพคน สัตว์ และพืชโดยอัตโนมัติ'],['one-health--oh-global-network--one-health-network-ในบริบทความปลอดภัยอาหาร','One Health network ในบริบทความปลอดภัยอาหาร','one health network ในบริบทความปลอดภัยอาหาร \n สถาบันภาครัฐที่ออกกฎหมาย \n ผู้เชี่ยวชาญที่ให้ความรู้ \n ผู้ผลิตและผู้บริโภค \n ภาคเอกชน เอกสารยกตัวอย่างบริษัทอาหารรายใหญ่ของไทย \n องค์กรระหว่างประเทศ เช่น who, fao, woah ที่กำหนดนโยบาย \n โครงสร้างความร่วมมือระดับโลกด้าน one health ปัจจุบันคือ quadripartite ซึ่งมีสี่องค์กร ได้แก่ fao, unep, who และ woah ทำงานร่วมกันที่รอยต่อ คน สัตว์ พืช และสิ่งแวดล้อม ไม่ใช่สามองค์กรอย่างที่เอกสารระบุเท่านั้น เพราะมีหน่วยงานด้านสิ่งแวดล้อมคือ unep รวมอยู่ด้วย']],'one-health--oh-risk-analysis':[['one-health--oh-risk-analysis--กรอบใหญ่ของ-food-risk-analysis','กรอบใหญ่ของ food risk analysis','กรอบใหญ่ของ food risk analysis \n codex (cac) จัดทำมาตรฐานสากลที่ sps ใช้กำหนดมาตรการด้านความปลอดภัยอาหารในคน \n food risk analysis อยู่ภายใต้ sps agreement \n การวิเคราะห์ความเสี่ยงมี 3 ส่วนคือ risk assessment (ประเมิน), risk management (จัดการ) และ risk communication (สื่อสาร) \n risk assessment ตอบว่าถ้ากินเข้าไปจะมีโอกาสป่วยมากน้อยแค่ไหน ถ้าเกินกว่าที่ยอมรับได้ก็ต้องจัดการ \n risk management เช่น กินให้น้อยลง กินให้สะอาด ป้องกันการปนเปื้อน \n risk communication เป็นหน้าที่ของกรมปศุสัตว์ในฐานะ risk manager \n เทคนิคช่วยจำที่ผู้สรุปเขียนไว้: วิเคราะห์ risk เท่ากับ ประเมิน บวก จัดการ บวก สื่อสาร \n risk analysis ตามนิยาม codex เป็นกระบวนการที่ประกอบด้วยสามส่วน คือ risk assessment, risk management และ risk communication ตรงกับที่เอกสารสรุปไว้ \n การวิเคราะห์ความเสี่ยงด้านอาหารผูกกับ sps agreement จริง เพราะนิยาม appropriate level of protection ที่ใช้ในการจัดการความเสี่ยงทางจุลชีววิทยาของ codex คือนิยามเดียวกับที่อยู่ในความตกลง sps ขององค์การการค้าโลก'],['one-health--oh-risk-analysis--risk-assessment-4-ขั้นตอน','Risk assessment 4 ขั้นตอน','risk assessment 4 ขั้นตอน \n 1. hazard identification ระบุอันตราย เช่น ระบุว่าเชื้อหรือสารใดเป็นอันตราย พร้อม taxonomy และ pathogenesis \n 2. hazard characterization อธิบายอันตราย ต้องรู้ว่าโดสที่ได้รับสัมพันธ์กับโอกาสป่วยอย่างไร จึงเท่ากับ dose-response assessment \n 3. exposure assessment ประเมินการสัมผัส ต้องเจอเชื้อก่อนจึงจะก่อโรค เป็นขั้นที่เกิดคู่ขนานกับขั้นที่ 2 \n 4. risk characterization อธิบายความเสี่ยง เป็นการรวม ความเข้มข้น ความชุก และปริมาณการบริโภค เข้าด้วยกัน \n จุดที่ต้องแยกให้ออก: hazard characterization ตอบเรื่อง dose-response ส่วน exposure assessment ตอบเรื่อง prevalence, concentration และปริมาณที่บริโภค และ risk characterization คือการบูรณาการสองขั้นนี้เข้าด้วยกัน \n risk assessment ตามนิยาม codex เป็นกระบวนการเชิงวิทยาศาสตร์สี่ขั้นตามลำดับ คือ hazard identification, hazard characterization, exposure assessment และ risk characterization ตรงกับที่เอกสารสรุป \n hazard characterization คือขั้นที่ตอบเรื่องความสัมพันธ์ระหว่างโดสกับโอกาสและความรุนแรงของการป่วย เพราะเป็นการประเมินลักษณะผลกระทบต่อสุขภาพของสิ่งคุกคาม และต้องทำ dose-response assessment ซึ่งนิยามว่าเป็นการหาความสัมพันธ์ระหว่างขนาดของการได้รับกับความรุนแรงหรือความถี่ของผลเสียต่อสุขภาพ \n risk characterization คือขั้นบูรณาการ เพราะนิยามระบุว่าเป็นการประมาณโอกาสเกิดและความรุนแรงของผลเสียต่อสุขภาพในประชากรหนึ่ง โดยอาศัยผลจาก hazard identification, hazard characterization และ exposure assessment รวมกัน พร้อมความไม่แน่นอนที่แนบมา'],['one-health--oh-risk-analysis--risk-management-alop-และ-fso','Risk management ALOP และ FSO','risk management alop และ fso \n risk management คือการทำให้ความเสี่ยงอยู่ในระดับที่ยอมรับได้ ภายใต้ sps protection \n alop (appropriate level of protection) คือผลกระทบที่เกิดขึ้นในระดับที่ยอมรับได้ วัดเป็น จำนวนเคสต่อปี \n แต่ alop วัดได้ยาก จึงแปลงเป็น fso (food safety objective) คือ ปริมาณการปนเปื้อนเชื้อที่ยอมรับได้ ณ จุดบริโภค ซึ่งเป็นค่าความเข้มข้น \n risk communication คือการที่ risk manager คุยกับผู้ทำ risk assessment และให้ข้อมูลกับ stakeholders \n alop เป็นแนวคิดหลักของการจัดการความเสี่ยง เพราะสะท้อนเป้าหมายด้านสาธารณสุขที่ประเทศหนึ่งประกาศไว้สำหรับความเสี่ยงจากอาหาร และใช้นิยามเดียวกับความตกลง sps \n fso เป็นตัวชี้วัดเชิงปริมาณที่ใช้แปลง alop ให้ปฏิบัติได้ โดยต้องกำหนดความถี่หรือความเข้มข้นสูงสุดของสิ่งคุกคามไว้ใน fso หรือ po และเกณฑ์ทางจุลชีววิทยาถูกใช้เพื่อทำให้ alop เป็นรูปธรรมผ่านตัวชี้วัดเหล่านี้ \n risk manager คือองค์กรภาครัฐระดับชาติหรือระหว่างประเทศที่รับผิดชอบการจัดการความเสี่ยง และหลักการของ codex กำหนดให้ risk manager ต้องสื่อสารสองทาง ทั้งกับ risk assessor และกับผู้มีส่วนได้ส่วนเสีย ตรงกับที่เอกสารอธิบายเรื่อง risk communication'],['one-health--oh-risk-analysis--risk-analysis-ตามแนวทาง-woah','Risk analysis ตามแนวทาง WOAH','risk analysis ตามแนวทาง woah \n risk เท่ากับ consequences ร่วมกับ chances \n risk analysis ของ woah มี 4 ส่วน โดยแยก hazard identification ออกมาเป็นอีกส่วนหนึ่ง ส่วนอีก 3 ข้อที่เหลือเหมือน food risk analysis \n เชื้อโรคทุกตัวไม่ได้เป็น hazard เพราะต้องก่อ consequences ต่อ host ที่ปลายทางด้วย \n ประเทศผู้ส่งออกเป็นผู้ทำการประเมินและตรวจสอบเพื่อยืนยันว่าสินค้าของตนปลอดโรค แม้ในทางระเบียบวิธีจะเกี่ยวข้องกับทั้งผู้ส่งออกและผู้นำเข้า \n องค์ประกอบ 4 ข้อของ woah risk assessment \n 1. entry assessment จุดเริ่มอยู่ที่ประเทศผู้ส่งออก ถ้าไม่มีการปนเปื้อนก็ไม่เกิด exposure \n 2. exposure assessment หาโอกาสที่ host ในประเทศผู้นำเข้าจะได้เจอกับ hazard ที่นำเข้ามา ถ้าไม่มี host ในประเทศผู้นำเข้าก็ไม่ถือเป็น hazard \n 3. consequence assessment เมื่อ host เจอ hazard แล้วเกิดการระบาดและเกิดผลกระทบ \n 4. risk estimation ประมาณความเสี่ยงโดยรวมผลของข้อ 1 ถึง 3 เข้าด้วยกัน \n risk analysis ตามแนวทาง woah มีสี่ส่วน คือ hazard identification, risk assessment, risk management และ risk communication ซึ่งแยก hazard identification ออกมาเป็นส่วนหนึ่งต่างหากจากอีกสามส่วน ตรงกับที่เอกสารสรุป \n risk assessment ของ woah ประกอบด้วยสี่องค์ประกอบเรียงลำดับ คือ entry assessment, exposure assessment, consequence assessment และ risk estimation โดย risk estimation คือการรวมผลจากสามขั้นแรกเข้าด้วยกันเพื่อให้ได้ค่าความเสี่ยงโดยรวม ตรงกับที่เอกสารสรุป \n เชื้อโรคทุกตัวไม่ได้เป็น hazard เพราะ hazard identification คือการระบุเฉพาะเชื้อที่มีศักยภาพก่อผลเสียจากการนำเข้าสินค้านั้น และต้องพิจารณาด้วยว่าเชื้อมีอยู่แล้วในประเทศผู้นำเข้าหรือไม่ และอยู่ภายใต้โครงการควบคุมหรือกำจัดหรือไม่'],['one-health--oh-risk-analysis--กรณีศึกษา-import-risk-assessment-ของกุ้งในออสเตรเลีย','กรณีศึกษา import risk assessment ของกุ้งในออสเตรเลีย','กรณีศึกษา import risk assessment ของกุ้งในออสเตรเลีย \n ผู้สรุปบันทึกว่าหัวข้อนี้ ไม่ได้ออกในข้อสอบของรุ่นก่อนหน้า แต่เป็นตัวอย่างที่เดินครบทั้ง 4 ขั้นของ woah จึงมีค่าในการทำความเข้าใจ \n ออสเตรเลียปลอดโรคสัตว์น้ำหลายชนิด การนำเข้ากุ้งดิบหรือกุ้งแช่แข็งจึงเสี่ยงต่อการนำเชื้อเข้าประเทศ \n hazard identification: wssv (white spot syndrome virus) เพราะพบได้ในกุ้งที่ดูปกติ และยังตรวจเจอได้ในกุ้งแช่แข็ง \n entry assessment \n ประเทศต้นทางมีความชุกสูง กุ้งที่ดูปกติอาจติดเชื้อแบบซ่อนเร้น และกุ้งแช่แข็งยังตรวจเจอ dna ของเชื้อได้ \n สรุป likelihood of entry เท่ากับ high \n exposure assessment \n แบ่งกลุ่มเสี่ยงเป็น 3 กลุ่ม พร้อมค่า partial likelihood of exposure (ple) \n ฟาร์มกุ้งทั่วไป เท่ากับ low \n โรงเพาะฟัก (hatchery) เท่ากับ high และเป็นกลุ่มที่สัมผัสเชื้อสูงที่สุด \n กุ้งธรรมชาติ (wild) เท่ากับ high เพราะกุ้งดิบอาจถูกทิ้งลงทะเลหรือใช้เป็นเหยื่อ \n consequence assessment \n การสูญเสียทางเศรษฐกิจ ฟาร์มล่ม ผลกระทบต่อการส่งออก และการเสียสถานะปลอดโรค \n สรุป overall likely consequence เท่ากับ high \n risk estimation \n palee (partial annual likelihood of entry and exposure) คือโอกาสรายปีที่เชื้อจะเข้าประเทศและไปถึง host ในแต่ละกลุ่ม \n palee เท่ากับ likelihood of entry คูณกับ partial likelihood of exposure \n ต้องแยกคำนวณรายกลุ่มเพราะแต่ละกลุ่ม host เสี่ยงไม่เท่ากัน \n partial annual risk เท่ากับผลรวมของ palee ของกลุ่มนั้นคูณกับ overall likely consequence และ overall annual risk คือผลรวมของ partial annual risk ทุกกลุ่ม \n ผลลัพธ์สำหรับ wssv: entry เท่ากับ high, exposure เท่ากับ low ถึง high, consequence เท่ากับ high และ overall annual risk เท่ากับ high \n alop และ risk management \n alop ของออสเตรเลียเท่ากับ very low เมื่อความเสี่ยงของ wssv เท่ากับ high ซึ่งสูงกว่า alop จึงต้องทำ risk management \n มาตรการที่กำหนด: นำเข้าจากประเทศหรือเขตปลอดโรค ตรวจ pcr ให้ได้ผลลบ แปรรูปกุ้งเช่นแกะเปลือกและเด็ดหัว ทำให้สุกที่อุณหภูมิไม่ต่ำกว่า 85 องศาเซลเซียส ติดฉลาก for human consumption only และตรวจซ้ำหลังเข้าประเทศ \n เป้าหมายคือลดความเสี่ยงลงให้ต่ำกว่า alop \n สมมติฐานของ entry assessment มีหลักฐานตรงรองรับ คือ ตรวจพบ wssv และ yellowhead virus ที่ยังมีชีวิตอยู่ในผลิตภัณฑ์กุ้งแช่แข็งที่นำเข้าออสเตรเลียเพื่อการบริโภคจากเอเชียตะวันออกเฉียงใต้ และการนำเข้าผลิตภัณฑ์ติดเชื้อดังกล่าวเสี่ยงต่อการถ่ายทอดเชื้อสู่ประชากรกุ้งธรรมชาติและกุ้งฟาร์มในประเทศ'],['one-health--oh-risk-analysis--รูปแบบข้อสอบของรุ่นก่อนหน้า','รูปแบบข้อสอบของรุ่นก่อนหน้า','รูปแบบข้อสอบของรุ่นก่อนหน้า \n หัวข้อนี้ของรุ่นก่อนหน้าออกเป็นภาษาไทย และเอกสารเก็บภาพข้อสอบไว้ 10 ข้อ ซึ่งวนอยู่กับนิยามของ 3 องค์ประกอบ 4 ขั้นตอน และองค์กรที่กำกับ ทั้งนี้ข้อสอบปีนี้อาจเปลี่ยนไป \n ผู้สรุปบันทึกคำถามที่เจอบ่อยไว้เป็นชุด: โดสสัมพันธ์กับโอกาสป่วยอยู่ขั้นใด ตอบ hazard characterization, prevalence อยู่ขั้นใด ตอบ exposure assessment, risk manager คุยกับผู้ประเมินคือขั้นใด ตอบ risk communication']],'one-health--oh-vet-role':[['one-health--oh-vet-role--บทนำ-ทำไม-one-health-ต้องมีสัตวแพทย์','บทนำ — ทำไม One Health ต้องมีสัตวแพทย์','บทนำ — ทำไม one health ต้องมีสัตวแพทย์ \n 9 เหตุผลที่สไลด์ยกมา (p.2) \n ประชากรมนุษย์เพิ่มขึ้น (increase of human population) \n การสัมผัสระหว่างคนกับสัตว์ป่าเพิ่มขึ้น (increase in human-wildlife contact) \n การเปลี่ยนแปลงของสิ่งแวดล้อม (environmental changes) \n การเดินทางระหว่างประเทศขยายตัว (expansion of international travel) \n การใช้ยาต้านจุลชีพและการดื้อยา (amu and amr) \n การคุ้มครองอาหาร (food protection) \n ประชากรกลุ่ม immunocompromised เพิ่มขึ้น \n การผลิตอาหารทางทะเล (marine food production) \n มลพิษจากจุลชีพและสารเคมี (microbial and chemical pollution) \n นิยามที่สไลด์ใช้ (p.3) \n one health คือ integrative effort of multiple disciplines ที่ทำงานร่วมกันทั้งระดับ local, national และ global เพื่อให้ได้ optimal health ของคน สัตว์ และสิ่งแวดล้อม \n สัตวแพทย์เป็น บุคลากรสุขภาพกลุ่มเดียวที่มีโอกาสได้เห็นทั้งตัวคนและสัตว์ของเขาพร้อมกัน (the only health care professional likely to see both people and their animals) \n ตัวเลขในสไลด์ (p.4) \n โรคในคนทั้งหมด 1,461 โรค มี 60% ที่เกิดจาก multi-host pathogens (สไลด์อ้าง avma 2008, gibbs and gibbs 2012) แต่ตัวเลขชุดนี้คลาดเคลื่อนจากต้นทาง ต้นฉบับคือ taylor et al., 2001 ซึ่งนับ เชื้อก่อโรคในคน 1,415 ชนิด (species) ไม่ใช่ 1,461 โรค และในจำนวนนี้ 868 ชนิด คิดเป็น 61% ที่เป็น zoonotic หน่วยที่ถูกต้องคือชนิดของเชื้อก่อโรค ไม่ใช่จำนวนโรค เวลาสอบให้ตอบตามสไลด์ว่า 1,461 และ 60% แต่ให้จำเลขต้นฉบับ 1,415 species กับ 61% zoonotic ไว้ด้วย \n ในช่วง 30 ปี ที่ผ่านมา โรคติดเชื้ออุบัติใหม่ในคน 75% เป็น zoonotic \n สัตวแพทย์คลินิกเกือบ 77% ทำงานกับ companion animals \n 8% ทำงานกับ food animals ส่วนสายงาน wildlife และ ecosystem health มีจำนวนเพิ่มขึ้นเรื่อยๆ \n จุดกำเนิดแนวคิด — calvin schwabe (p.5) \n calvin schwabe, dvm เป็น veterinary epidemiologist หนังสือ veterinary medicine and human health (1984) ของเขาคือจุดเริ่มของแนวคิด one health สมัยใหม่ \n schwabe เสนอ combined medical and veterinary approach สำหรับการป้องกันและควบคุม zoonoses \n สไลด์เดียวพิมพ์ครบทั้งชื่อคน ชื่อหนังสือ ปี และแนวคิด จำเป็นชุดเดียวไปเลย schwabe, veterinary medicine and human health, 1984, combined medical and veterinary approach \n จากเชื้อก่อโรคในคนที่จัดว่าเป็น emerging จำนวน 175 ชนิด มี 132 ชนิด คิดเป็น 75% ที่เป็น zoonotic และโดยรวมแล้วเชื้อ zoonotic มีโอกาสสัมพันธ์กับโรคอุบัติใหม่มากกว่าเชื้อที่ไม่ใช่ zoonotic ประมาณ 2 เท่า \n แนวคิด one medicine หรือ one health ในรูปแบบสมัยใหม่ถูกเรียบเรียงขึ้นใหม่ในหนังสือ veterinary medicine and human health ฉบับปี 1984 ของ calvin schwabe'],['one-health--oh-vet-role--ภาพรวม-8-ประเด็น-one-health-ที่สัตวแพทย์เกี่ยวข้อง','ภาพรวม — 8 ประเด็น One Health ที่สัตวแพทย์เกี่ยวข้อง','ภาพรวม — 8 ประเด็น one health ที่สัตวแพทย์เกี่ยวข้อง \n 1. emerging infectious diseases \n 2. public health \n 3. food safety \n 4. companion animals \n 5. antimicrobial resistance \n 6. bioterrorism \n 7. environmental pollution \n 8. global climate change \n เนื้อหาที่เหลือทั้งเลกเชอร์เดินตามลำดับ 8 ข้อนี้เป๊ะๆ ใช้สไลด์นี้เป็น checklist ทวนก่อนสอบได้เลย \n เชื้อก่อโรคในคนที่มีการทบทวนอย่างเป็นระบบมี 1,415 ชนิด โดย 868 ชนิด (61%) เป็น zoonotic และในกลุ่มที่จัดว่าเป็นเชื้ออุบัติใหม่ 175 ชนิด มี 132 ชนิด (75%) ที่เป็น zoonotic ทั้งนี้เชื้อ zoonotic มีโอกาสสัมพันธ์กับโรคอุบัติใหม่มากกว่าเชื้อที่ไม่ใช่ zoonotic ประมาณ 2 เท่า \n จากฐานข้อมูลเหตุการณ์โรคอุบัติใหม่ 335 เหตุการณ์ระหว่างปี 1940-2004 พบว่า 60.3% เป็น zoonoses และ 71.8% ของ zoonoses เหล่านั้นมีต้นกำเนิดจากสัตว์ป่า อีกทั้งจุดกำเนิดของโรคอุบัติใหม่สัมพันธ์อย่างมีนัยสำคัญกับปัจจัยด้านเศรษฐกิจสังคม สิ่งแวดล้อม และนิเวศวิทยา ซึ่งเป็นเหตุผลเชิงหลักฐานที่ทำให้วาระ one health ของสัตวแพทย์ต้องครอบคลุมทั้งโรคอุบัติใหม่ สัตว์ป่า และมิติสิ่งแวดล้อม ไม่ใช่แค่โรคติดเชื้อในสัตว์เลี้ยง'],['one-health--oh-vet-role--ประเด็นที่-1-emerging-infectious-diseases-ohzdp-และการกำจัดโรคพิ','ประเด็นที่ 1 — Emerging infectious diseases, OHZDP และการกำจัดโรคพิษสุนัขบ้า','ประเด็นที่ 1 — emerging infectious diseases, ohzdp และการกำจัดโรคพิษสุนัขบ้า \n ขนาดของปัญหาและตัวอย่าง (p.7) \n โรคติดเชื้อทั่วโลกทำให้เสียชีวิต มากกว่า 13 ล้านคนต่อปี (taylor et al., 2001, who, 1999) \n 75% ของโรคติดเชื้ออุบัติใหม่เป็น zoonotic (taylor et al., 2001, who, 1999) \n ตัวอย่างที่สไลด์ยกมา ได้แก่ ebola virus ระบาดในแอฟริกากลาง, nipah virus ในมาเลเซียและสิงคโปร์, avian influenza ในฮ่องกง, hantavirus และ west nile virus ในสหรัฐฯ \n ตัวเลข 75% โผล่ 2 ครั้งในเลกเชอร์เดียวกัน คือ p.4 เขียนแบบ over the past 30 years และ p.7 เขียนแบบกว้างๆ ว่า 75% of eids are zoonotic เป็นตัวเลขเดียวกันแต่คนละสำนวน อย่าตกใจถ้าโจทย์ถามคนละแบบ \n บทบาทสัตวแพทย์ต่อ eids (p.8) \n ระบุ source of infection ของโรค \n ระบุ route of transmission \n ระบุ nature ของโรคติดเชื้ออุบัติใหม่ \n ohzdp — 5 โรค zoonotic ที่ถูกจัดลำดับความสำคัญ (p.9) \n 1. zoonotic avian influenza เพราะอัตราตายในคนสูงและมีโอกาส reassortment กลายเป็นสายพันธุ์ระบาดใหญ่ \n 2. emerging coronaviruses เพราะแพร่ทั่วโลกได้เร็วและกระทบเศรษฐกิจสังคมมหาศาล \n 3. nipah virus เพราะ case-fatality rate สูงและยังไม่มีการรักษาจำเพาะหรือวัคซีน \n 4. rabies เพราะเกือบ 100% fatal \n 5. ebola เพราะเสี่ยงต่อการนำเข้าจากต่างประเทศ \n rabies สไลด์ระบุว่า nearly 100% fatal และย้ำว่า mass vaccination กับ surveillance ยังเป็นมาตรการควบคุมที่สำคัญที่สุด \n ebola ไม่เป็นโรคประจำถิ่นในประเทศไทย แต่ยังติดอยู่ในลิสต์ ohzdp ด้วยเหตุผลเรื่องความเสี่ยงจากการนำเข้าข้ามประเทศ ข้อนี้เป็นจุดที่โจทย์ชอบหลอก \n 7 องค์ประกอบยุทธศาสตร์กำจัดโรคพิษสุนัขบ้า (p.10) \n surveillance, control และ prevention ทั้งในคนและในสัตว์ \n การควบคุมประชากรสัตว์ (animal population control) \n การประเมินโครงการ (project evaluation) \n การมีส่วนร่วมของชุมชน (community participation) \n การประชาสัมพันธ์ (public relations) \n การจัดการข้อมูล (information management) \n นวัตกรรมและการถ่ายทอดเทคโนโลยี (innovation and technology transfer) \n 6 ความรับผิดชอบของสัตวแพทย์ในการป้องกันและควบคุม zoonoses (p.11) \n 1. ปกป้องคนจากการสัมผัสโรคที่ติดจากสัตว์ \n 2. ปกป้องสัตว์จากการติดเชื้อ zoonotic \n 3. ให้ความรู้เจ้าของสัตว์และประชาชนให้ป้องกันตัวเองได้ \n 4. ใช้ epidemiology (herd health medicine) หาแหล่งโรคและ transmission dynamics \n 5. ทำ disease surveillance และ eradication programs \n 6. ป้องกันและควบคุมโรค \n โรคพิษสุนัขบ้าที่หมุนเวียนในประชากรสุนัขทำให้คนเสียชีวิตทั่วโลกประมาณ 59,000 คนต่อปี และการฉีดวัคซีนในสุนัขเป็นมาตรการเดี่ยวที่ลดภาระโรคได้มากที่สุด'],['one-health--oh-vet-role--ประเด็นที่-2-บทบาทด้านสาธารณสุขของสัตวแพทย์','ประเด็นที่ 2 — บทบาทด้านสาธารณสุขของสัตวแพทย์','ประเด็นที่ 2 — บทบาทด้านสาธารณสุขของสัตวแพทย์ \n พัฒนาระบบเกษตรและระบบอาหาร (improve agriculture and food systems) \n ผลักดันงานวิจัย biomedical และ comparative medicine \n ป้องกันและควบคุมโรค zoonotic \n ส่งเสริมสุขภาพสิ่งแวดล้อมและระบบนิเวศ (environmental and ecosystem health) \n veterinary public health (vph) เป็นคำที่ who ใช้อย่างเป็นทางการสำหรับกิจกรรมสาธารณสุขที่นำความรู้ ความเชี่ยวชาญ และทรัพยากรทางสัตวแพทยศาสตร์มาปกป้องและยกระดับสุขภาพคน โดยทำหน้าที่เป็นข้อต่อ (linkage) ระหว่างภาคเกษตรกับภาคสาธารณสุข และการควบคุมกำจัด zoonoses กับ food protection ยังคงเป็นหน้าที่หลักของ vph \n งาน biomedical models หรือ comparative medicine เป็นองค์ประกอบหนึ่งของโปรแกรม veterinary public health อย่างเป็นทางการ ร่วมกับงาน zoonoses, foot and mouth disease, food protection, การศึกษาและฝึกอบรม และการพัฒนาระบบบริการ vph'],['one-health--oh-vet-role--ประเด็นที่-3-ความปลอดภัยอาหาร-จากฟาร์มถึงโต๊ะอาหาร','ประเด็นที่ 3 — ความปลอดภัยอาหาร จากฟาร์มถึงโต๊ะอาหาร','ประเด็นที่ 3 — ความปลอดภัยอาหาร จากฟาร์มถึงโต๊ะอาหาร \n เชื้อก่อโรคและมิติใหม่ของ food safety (p.14) \n เชื้อ foodborne ทั้งดั้งเดิมและอุบัติใหม่ที่สไลด์ระบุชื่อ ได้แก่ escherichia, salmonella, campylobacter และ listeria \n 4 new dimensions ของ food safety คือ การขนส่งอาหารระหว่างประเทศ, ความต้องการโปรตีนจากสัตว์ที่เพิ่มขึ้น, globalization ของห่วงโซ่อาหาร และโอกาสการแพร่กระจายของโรคติดเชื้อ \n อาหารเป็น vehicle ของการแพร่โรคได้ ผลิตในท้องถิ่นแต่กระจายทั่วโลก ทำให้เชื้อข้ามพรมแดนได้ ภายในไม่กี่ชั่วโมง \n farm to fork 5 ขั้น (p.15) \n farm production → animal health management → processing & slaughter → inspection & monitoring → consumer \n บทบาทสัตวแพทย์ในสายนี้คือ ดูแลการผลิตอาหารตั้งแต่ farm to fork, จัดการระบบนิเวศ และแก้ปัญหาการปนเปื้อนของจุลชีพ \n ความรับผิดชอบต่ออาหาร 3 กิจกรรม (p.16) \n การผลิตสัตว์ที่มีสุขภาพดี (production of healthy animals) \n การฆ่าและแปรรูปสัตว์เพื่อการบริโภค (slaughter and processing) \n การตรวจสอบผลิตภัณฑ์จากสัตว์ (inspection of animal products) \n ทั้ง 3 กิจกรรมครอบคลุม food quantity, food quality และ food safety \n สไลด์ p.16 พิมพ์คำว่า quantity, quality, safety ไว้ด้วยกัน จำเป็นชุด 3 คำนี้ อย่าตอบแค่ safety อย่างเดียวเวลาโจทย์ถามว่าสัตวแพทย์รับผิดชอบอะไรบ้างในอาหาร \n สาเหตุของการเจ็บป่วยจากอาหารที่พบบ่อยที่สุดคือเชื้อกลุ่มที่ทำให้เกิดอุจจาระร่วง โดยเฉพาะ norovirus และ campylobacter spp. ส่วนสาเหตุการเสียชีวิตจากโรคที่เกิดจากอาหารส่วนใหญ่คือ non-typhoidal salmonella enterica'],['one-health--oh-vet-role--ประเด็นที่-4-สัตว์เลี้ยงเป็นเพื่อน-companion-animals','ประเด็นที่ 4 — สัตว์เลี้ยงเป็นเพื่อน (Companion animals)','ประเด็นที่ 4 — สัตว์เลี้ยงเป็นเพื่อน (companion animals) \n 57% ของครัวเรือนในสหรัฐฯ เลี้ยงสุนัข แมว หรือทั้งสองอย่าง และยังมี exotic animals, นก และสัตว์เลื้อยคลานอีกหลายล้านตัวที่ถูกเลี้ยงเป็นสัตว์เลี้ยง \n บทบาทสัตวแพทย์คือ ให้ความรู้ประชาชนเรื่องการป้องกัน zoonoses \n ฉีดวัคซีนป้องกันโรค zoonotic ในสัตว์เลี้ยง โดยสไลด์ระบุชื่อไว้ 2 โรคคือ rabies และ leptospirosis \n ลด ectoparasites และพยาธิในทางเดินอาหารโดยเฉพาะ roundworms \n การฉีดวัคซีนพิษสุนัขบ้าในสุนัขเป็นมาตรการที่ตรงจุดที่สุดสำหรับสุขภาพคน เพราะมีผู้เสียชีวิตจากพิษสุนัขบ้ามากกว่า 50,000 รายต่อปี ส่วนใหญ่เป็นเด็กในประเทศกำลังพัฒนา และเกือบทั้งหมดถูกสุนัขกัด ทั้งนี้ประสบการณ์จากประเทศพัฒนาแล้วและโครงการที่ดำเนินอยู่ในละตินอเมริกา แอฟริกา และเอเชีย แสดงว่าการกำจัดโรคพิษสุนัขบ้าในสุนัขเป็นเป้าหมายที่ทำได้จริง \n การถ่ายพยาธิสัตว์เลี้ยงตามความเสี่ยงเป็นมาตรการลด zoonotic risk ที่มีตัวเลขกำกับ โดยความถี่ที่แสดงว่าจำเป็นต่อการลดการปล่อยไข่ toxocara spp. ที่ติดสู่คนคือ 4 ครั้งต่อปี แต่จากการสำรวจเจ้าของสัตว์เลี้ยง 5,001 รายใน 5 ประเทศยุโรป สุนัขถ่ายพยาธิเฉลี่ยเพียง 2.3 ครั้งต่อปีและแมว 2.2 ครั้งต่อปี ทั้งที่ 93% ของสุนัขและ 54% ของแมวจัดอยู่ในกลุ่มเสี่ยงสูงสุด \n การตรวจพบ leptospirosis ในสัตว์แต่เนิ่นสามารถใช้เป็นตัวชี้การปนเปื้อนของสิ่งแวดล้อม และเป็นตัวจุดชนวนมาตรการป้องกัน เช่น การฉีดวัคซีนในสัตว์เลี้ยงและปศุสัตว์ การใช้น้ำสะอาด และการสวมชุดกันน้ำเมื่อต้องสัมผัสแหล่งน้ำที่อาจปนเปื้อน'],['one-health--oh-vet-role--ประเด็นที่-5-การดื้อยาต้านจุลชีพและแผน-amr-ของไทย','ประเด็นที่ 5 — การดื้อยาต้านจุลชีพและแผน AMR ของไทย','ประเด็นที่ 5 — การดื้อยาต้านจุลชีพและแผน amr ของไทย \n amu และการแพร่ของ resistance ในห่วงโซ่อาหาร (p.18) \n วัตถุประสงค์ของการใช้ยาต้านจุลชีพมี 3 ข้อ คือ treatment, prophylaxis และ growth promotion \n สไลด์แสดงการแพร่ของ resistance ข้ามห่วงโซ่อาหารเป็น 4 compartments โดยพิมพ์เส้นทางไว้ว่า livestock and aquaculture → food products → humans \n amr ในห่วงโซ่อาหารคุกคามความสำเร็จของการรักษาและการป้องกันโรคติดเชื้อ \n amr one health continuum 3 compartments (p.19, robinson et al., 2016) \n humans การใช้ยาทางคลินิกและการติดเชื้อดื้อยาในสถานพยาบาล \n animals & agriculture การใช้ยาในปศุสัตว์และสัตว์น้ำเพื่อ treatment, prophylaxis และ growth promotion \n environment แบคทีเรียดื้อยาและ residues ที่เข้าสู่ดินและน้ำจากของเสียและ runoff \n แผนปฏิบัติการ amr แห่งชาติของไทย ฉบับที่ 2 ปี 2023-2027 (p.20) \n 1. ลดการป่วยจาก amr ในคน เป้าหมาย 10% \n 2. ลดการใช้ยาต้านจุลชีพ เป้าหมาย 10% ในคน และ 50% ในสัตว์ (สไลด์พิมพ์ไว้ว่า 10%/50%) \n 3. เพิ่มความรู้และความตระหนักของประชาชนเรื่อง amu เป้าหมาย 30% \n 4. ลดความเสี่ยง amr ในอาหารและสิ่งแวดล้อม (ไม่มีตัวเลขเป้าหมายพิมพ์ไว้) \n 5. เสริมความเข้มแข็งของการจัดการ amr (ไม่มีตัวเลขเป้าหมายพิมพ์ไว้) \n อย่าสลับตัวเลข ลด amu ในคน 10% แต่ในสัตว์ 50% และมีเพียง 3 จาก 5 objectives เท่านั้นที่มีตัวเลขเป้าหมายพิมพ์บนสไลด์ ข้อ 4 และ 5 ไม่มีตัวเลข \n บทบาทสัตวแพทย์ต่อ amr (p.22, who, 2015) \n สัตวแพทย์สาย pharmacology และยาทำงานข้ามสาขา ทั้งสัตว์เลี้ยงและสัตว์เศรษฐกิจ ครอบคลุม food security และการควบคุม drug residue ของภาครัฐ \n ความสำคัญของ prudent antibiotic use ภายใต้แนวคิด one health เพิ่มขึ้นเรื่อยๆ \n ติดตาม (monitoring) ทั้ง amu และ amr ในปศุสัตว์และสัตว์น้ำ \n amr เชื่อมโยงกับทั้งสาม domain ของ one health คือ คน สัตว์ และสิ่งแวดล้อม โดยการใช้ยาต้านจุลชีพในการผลิตสัตว์ในขนาด sub-therapeutic ร่วมกับระยะเวลาสัมผัสยาที่ยาวนาน สร้างสภาวะที่เหมาะสมให้แบคทีเรียตรึงยีนที่ทำให้ดื้อยาไว้ และยีนเหล่านี้ถูกถ่ายทอดต่อไปยังเชื้อก่อโรคในคนหรือ gut microbiota ของคนได้ผ่านคน อาหารที่ปนเปื้อน หรือสิ่งแวดล้อม'],['one-health--oh-vet-role--ประเด็นที่-6-bioterrorism','ประเด็นที่ 6 — Bioterrorism','ประเด็นที่ 6 — bioterrorism \n นิยามและตัวอย่างในอดีต (p.23) \n bioterrorism คือการใช้จุลชีพ ได้แก่ bacteria, viruses และ fungi หรือ toxins สร้างเป็นอาวุธที่ก่อให้เกิดความตายและโรคในคน สัตว์ และพืช \n ตัวอย่างในอดีตที่สไลด์ยกมา ได้แก่ การทิ้งศพลงบ่อน้ำของศัตรูเพื่อวางยาน้ำดื่ม, ผ้าห่มปนเปื้อน smallpox, การจงใจปนเปื้อน salmonella ในสลัดบาร์, จดหมายที่มี anthrax รวมถึงการใช้ botulism, tularemia และ hemorrhagic fever เป็นอาวุธชีวภาพ \n 3 บทบาทของสัตวแพทย์ (p.24) \n surveillance เฝ้าระวังเชื้อที่ใช้ก่อการร้ายชีวภาพ \n treatment and disease control รักษาและควบคุมโรค \n early warning systems ระบบเตือนภัยล่วงหน้า \n การแบ่งงานระหว่าง animal health กับ law enforcement (p.25) \n เป้าหมายร่วมของทั้งสองฝ่ายคือ protect public health and safety \n ฝ่าย animal health ในภาวะปกติ ดูแลสวัสดิภาพสัตว์, ป้องกันการระบาดในสัตว์, หยุดยั้งไม่ให้เกิดเคสและการระบาดเพิ่ม, สอบสวนทางระบาดวิทยา และสร้างฐานความรู้ทางวิทยาศาสตร์เพื่อการป้องกันในอนาคต \n ฝ่าย animal health เมื่อเกิด deliberate release ต้องตรวจจับเหตุการณ์โรคที่น่าสงสัยและให้ความเชี่ยวชาญเฉพาะทาง \n ฝ่าย law enforcement ในภาวะปกติ สนับสนุนมาตรการด้านสุขภาพและรักษาความสงบเรียบร้อย \n ฝ่าย law enforcement เมื่อเกิด deliberate release ต้องปราบ agrocrimes และ agroterrorism, สกัดการโจมตีซ้ำ, รักษาหลักฐาน, สอบสวนทางอาญา และระบุตัวผู้ก่อเหตุ ผู้สมรู้ร่วมคิด พยาน และผู้เสียหาย \n เหตุการณ์ที่สไลด์ยกว่า \'จงใจปนเปื้อน salmonella ในสลัดบาร์\' คือการระบาดจริงที่เมือง the dalles รัฐ oregon ปี 1984 มีผู้ป่วย 751 ราย จากเชื้อ salmonella typhimurium และการสอบสวนทางอาญาภายหลังพบว่าสมาชิกของชุมชนศาสนาแห่งหนึ่งจงใจปนเปื้อนสลัดบาร์ โดยเชื้อที่พบในห้องปฏิบัติการของชุมชนนั้นแยกไม่ออกจากสายพันธุ์ที่ก่อการระบาด \n เหตุผลที่สัตวแพทย์ถูกวางไว้ในบทบาท surveillance และ early warning ของงาน bioterrorism คือ เชื้อก่อโรคอุบัติใหม่และเชื้อที่ใช้ก่อการร้ายชีวภาพส่วนใหญ่เป็น zoonotic และสัตว์ไวต่อสารชีวภาพบางชนิดมากกว่าคน จึงใช้เป็น clinical sentinel เพื่อการตรวจจับล่วงหน้าได้ ทั้งนี้การเฝ้าระวัง zoonotic ที่แยกส่วนกันเป็นข้อจำกัดสำคัญ ต้องอาศัยความร่วมมือระหว่างหน่วยงานทุกระดับ'],['one-health--oh-vet-role--ประเด็นที่-7-มลพิษสิ่งแวดล้อมและการใช้สัตว์เป็น-sentinel','ประเด็นที่ 7 — มลพิษสิ่งแวดล้อมและการใช้สัตว์เป็น sentinel','ประเด็นที่ 7 — มลพิษสิ่งแวดล้อมและการใช้สัตว์เป็น sentinel \n ภาระโรคจากสิ่งแวดล้อม (p.26, barrett et al., 2011) \n 24% ของ global burden of disease มาจากสิ่งแวดล้อม \n 23% ของการเสียชีวิตทั่วโลกทั้งหมดเกิดจากปัจจัยด้านสิ่งแวดล้อม \n สองตัวเลขนี้อยู่สไลด์เดียวกันและใกล้กันมาก แยกให้ชัด 24% คือ burden of disease ส่วน 23% คือ deaths \n แนวคิด sentinel (p.26) \n อาหารสามารถทำหน้าที่เป็น sentinel สำหรับติดตามการปนเปื้อนในสิ่งแวดล้อม ตัวอย่างที่สไลด์ยกคือการปนเปื้อนสารชีวฆาต (biocide)ในน้ำผึ้ง \n animal sentinels ช่วยให้ตรวจจับและจัดการความเสี่ยงสุขภาพร่วมได้เร็วและมีประสิทธิภาพมากขึ้น \n การปนเปื้อนจากภาคเกษตรอาจนำไปสู่การปนเปื้อนในอาหารที่มาจากสัตว์ \n เส้นทางการเฝ้าระวังสารชีวฆาต (biocide)ด้วยผึ้ง (p.27, cirelli et al., 2026) \n สารชีวฆาต (biocide)ปนเปื้อนพืชนอกเป้าหมาย (off-target contamination) \n เกสรผึ้งปนเปื้อนและผึ้ง apis mellifera ซึ่งเป็น pollinator ได้รับสัมผัส \n นำการวิเคราะห์สารชีวฆาต (biocide)ในเกสรผึ้ง มารวมกับการระบุ botanical origin, ข้อมูลอุตุนิยมวิทยา และบันทึกการใช้สารเคมี เพื่อเข้าใจกระบวนการกระจายตัวของสารในภูมิทัศน์เกษตร \n 23% ของการเสียชีวิตทั่วโลก และ 22% ของ dalys ทั่วโลกในปี 2012 เกิดจากปัจจัยเสี่ยงด้านสิ่งแวดล้อมที่ปรับเปลี่ยนได้'],['one-health--oh-vet-role--ประเด็นที่-8-การเปลี่ยนแปลงสภาพภูมิอากาศและความรับผิดชอบด้านสิ่ง','ประเด็นที่ 8 — การเปลี่ยนแปลงสภาพภูมิอากาศและความรับผิดชอบด้านสิ่งแวดล้อม','ประเด็นที่ 8 — การเปลี่ยนแปลงสภาพภูมิอากาศและความรับผิดชอบด้านสิ่งแวดล้อม \n ผลของ climate change ต่อโรค (p.28) \n เพิ่มความเสี่ยงของโรคที่มีแมลงเป็นพาหะ (vector-borne diseases) โดยสไลด์ยกตัวอย่าง yellow fever และ encephalitis \n อุณหภูมิที่สูงขึ้นและฤดูหนาวที่สั้นลงทำให้ขอบเขตของโรคเขตร้อนขยายตัว โดยสไลด์ยกตัวอย่าง dengue และ malaria \n บทบาทสัตวแพทย์คือ สร้างความตระหนักถึงผลของ climate change ต่อสุขภาพสัตว์ zoonoses และสาธารณสุข พร้อมทั้งเฝ้าระวังและตอบสนองต่อโรคที่เกิดจาก climate change \n สไลด์แยกกลุ่มตัวอย่างไว้คนละบรรทัด yellow fever กับ encephalitis อยู่ในกลุ่ม vector-borne ส่วน dengue กับ malaria อยู่ในกลุ่มโรคเขตร้อนที่ขยายพื้นที่ตามอุณหภูมิ \n 2 ความรับผิดชอบด้านสุขภาพสิ่งแวดล้อมของสัตวแพทย์ (p.29) \n 1. ปกป้องสิ่งแวดล้อมทั้งในชนบทและในเมืองจากความเสื่อมโทรมที่เกิดจากการเลี้ยงสัตว์หนาแน่น \n 2. ปกป้องคนและสัตว์จากผลกระทบทางสิ่งแวดล้อม \n ทำผ่าน 4 การกระทำ ได้แก่ ระบุแหล่งน้ำที่ปลอดภัย, ให้คำแนะนำเรื่องการปกป้องแหล่งน้ำ, วินิจฉัยโรคที่มากับน้ำและภาวะพิษ, และให้คำแนะนำเรื่องอันตรายต่อสุขภาพคนที่เกี่ยวข้องกับสัตว์และของเสียจากสัตว์ \n แบบจำลองที่พารามิเตอร์มาจากข้อมูลจริงของ aedes aegypti และ ae. albopictus คาดว่าการเปลี่ยนแปลงสภาพภูมิอากาศจะทำให้พื้นที่เสี่ยงการถ่ายทอดไวรัสที่มียุงลายเป็นพาหะ เช่น dengue, chikungunya และ zika เคลื่อนไปทางขั้วโลกและเพิ่มขึ้นอย่างมาก โดยในกรณีเลวร้ายที่สุดจะมีประชากรเกือบหนึ่งพันล้านคนถูกเพิ่มความเสี่ยงใหม่ภายในศตวรรษนี้ \n climate change กระทบสุขภาพสัตว์ผ่าน 4 ทาง คือ โรคและความเครียดจากความร้อน เหตุการณ์สภาพอากาศรุนแรง การปรับระบบการผลิตสัตว์เข้าสู่สภาพแวดล้อมใหม่ และการอุบัติหรืออุบัติซ้ำของโรคติดเชื้อโดยเฉพาะโรคที่มีแมลงเป็นพาหะ ซึ่งขึ้นกับสภาพภูมิอากาศอย่างมาก จึงต้องมี veterinary services ที่เข้มแข็งและประสานกับงานสาธารณสุข เพราะจุดอ่อนของ veterinary services บั่นทอนเครือข่ายเฝ้าระวังระดับโลกที่จำเป็นต่อการตรวจจับภัยแต่เนิ่น'],['one-health--oh-vet-role--บทสรุป-อุปสรรค-โอกาส-และข้อเสนอแนะปิดท้าย','บทสรุป — อุปสรรค โอกาส และข้อเสนอแนะปิดท้าย','บทสรุป — อุปสรรค โอกาส และข้อเสนอแนะปิดท้าย \n 4 challenges และ 2 opportunities (p.30) \n challenges ได้แก่ ความยากในการร่วมมือระหว่างวิชาชีพ, การประสานงานและการสื่อสารที่ไม่มีประสิทธิภาพ, การทำงานข้ามศาสตร์ร่วมกันไม่ได้จริง และการขาดทรัพยากร \n opportunities มี 2 ข้อ คือ การร่วมมือที่ดีขึ้นกับแพทย์ เจ้าหน้าที่สาธารณสุข และนักวิชาชีพด้านสัตว์ป่าและสิ่งแวดล้อม ทำให้เข้าใจโรคได้ดีขึ้น และการควบคุมป้องกันโรคที่มีประสิทธิภาพมากขึ้น \n 4 ข้อเสนอแนะสำหรับสัตวแพทย์ (p.31) \n 1. เพิ่มการสื่อสารข้ามศาสตร์ \n 2. เข้าไปเป็นส่วนหนึ่งของกระบวนการวางแผน ดำเนินการ บริหารจัดการ และให้คำปรึกษาในกิจกรรม one health ทุกระดับ \n 3. เข้าร่วมกับ one health initiatives ทั้งระดับท้องถิ่น ระดับชาติ และระดับโลก \n 4. ไม่จำกัดตัวเองอยู่แค่งานคลินิกสัตว์ แต่เข้าไปทำงานด้านสาธารณสุข สุขภาพสิ่งแวดล้อม และการควบคุมความปลอดภัยอาหารด้วย'],['one-health--oh-vet-role--ทำไมสัตว์เลี้ยงจึงเป็น-sentinel-ที่ดี','ทำไมสัตว์เลี้ยงจึงเป็น sentinel ที่ดี','ทำไมสัตว์เลี้ยงจึงเป็น sentinel ที่ดี \n สัตว์เลี้ยง แชร์สิ่งแวดล้อมร่วมกับคน \n ใช้วัดการ exposure ในกรณีที่การวัดในคนทำได้ยาก ไม่ practical หรือผิดจริยธรรม \n สัตว์มี พฤติกรรมเสี่ยงต่อการได้รับสารเคมีมากกว่า เช่น เลีย คลุกดิน ดม \n อาจได้รับสารเคมีมากกว่า และมี latency ของโรคสั้นกว่าคน จึงแสดงอาการก่อน \n เหตุผลที่สัตว์เลี้ยงเป็น sentinel ที่ดี คือสัตว์อาจได้รับสัมผัสน้ำและอากาศที่ปนเปื้อนมากกว่า และไวต่อการสัมผัสสารปนเปื้อนมากกว่าคนที่อยู่ในพื้นที่เดียวกัน เหตุการณ์ป่วยในสัตว์จึงให้ข้อมูลแบบ sentinel ที่ใช้ประเมินความเสี่ยงต่อสุขภาพคนได้ \n การใช้ silicone passive sampler ในรูปแท็กห้อยปลอกคอสุนัขเพื่อติดตามการสัมผัสสารเคมีเป็นวิธีที่มีการตรวจสอบจริง โดยระดับสารในแท็กซิลิโคนของสุนัขสัมพันธ์กับ biomarker ในปัสสาวะ และคนกับสุนัขในบ้านเดียวกันได้รับสารกำจัดศัตรูพืชในระดับใกล้เคียงกัน'],['one-health--oh-vet-role--บทบาทสัตวแพทย์ในการปกป้องสุขภาพคนและสัตว์','บทบาทสัตวแพทย์ในการปกป้องสุขภาพคนและสัตว์','บทบาทสัตวแพทย์ในการปกป้องสุขภาพคนและสัตว์ \n แจ้งเจ้าของ ให้ไปตรวจร่างกายกับแพทย์ \n แจ้งหน่วยงานสาธารณสุข ให้เข้าไปตรวจสิ่งแวดล้อม \n การใช้สัตว์เป็น sentinel ของอันตรายในสิ่งแวดล้อมเป็นขอบเขตงานหนึ่งของ veterinary public health อย่างเป็นทางการ ร่วมกับการควบคุมโรคสัตว์สู่คน ความปลอดภัยอาหาร สุขภาพสัตว์และความปลอดภัยทางชีวภาพ จึงเป็นบทบาทของสัตวแพทย์ที่ต้องส่งต่อข้อมูลออกไปนอกคลินิก'],['one-health--oh-vet-role--indoor-environmental-toxicants-6-ชนิด','Indoor environmental toxicants 6 ชนิด','indoor environmental toxicants 6 ชนิด \n 1. teflon (ptfe) \n กระทะที่ ร้อนเกิน 280 องศาเซลเซียส จะปล่อย ptfe fumes ซึ่งเป็นพิษ \n นกได้รับแล้วตายภายใน 30 นาที \n คนที่สูดไอเข้าไปเกิด polymer fume fever อาการคล้ายหวัด ไอ หายใจลำบาก \n มักถูกวินิจฉัยผิดว่าเป็นหวัดหรือไวรัส ถ้าไม่รู้ว่ามีสัตว์ตายก่อน \n รูปแบบของปรอท \n ปรอทมี 3 รูปแบบหลัก คือ elemental, inorganic และ organic \n แบคทีเรียเปลี่ยน inorganic mercury ไปเป็น organic mercury ซึ่งเป็นพิษมากขึ้น \n 2. organic mercury \n ตัวที่พบบ่อยคือ methylmercury \n สะสมในสมองและระบบประสาท \n ได้รับจาก ปลาและอาหารทะเล หรือโรงงานที่ปล่อยสารลงน้ำ \n มักอยู่ในรูปของแข็ง ผ่านทางเดินอาหารและผิวหนังได้ดี \n 3. elemental mercury \n แหล่ง: amalgam, เทอร์โมมิเตอร์, หลอดไฟฟลูออเรสเซนต์ \n ได้รับ ทางการสูดดมเป็นหลัก \n ในสัตว์อาจเกิด ards ภายในไม่กี่นาทีถึงชั่วโมง \n คนอาจมีอาการไอ หายใจเร็ว และ hypoxia ซึ่งมักถูกวินิจฉัยผิดเป็นปอดอักเสบ \n ถ้ามี sentinel animal เช่น สุนัขหรือแมวป่วยก่อน จะช่วยให้วินิจฉัยเร็วขึ้น \n 4. lead \n แหล่ง: สีเก่า ท่อ แบตเตอรี่ ลูกกระสุน \n ได้รับทาง oral \n อาการ: ระบบประสาทร่วมกับทางเดินอาหาร ทั้งในสัตว์และคน \n เด็กเล็กและหญิงตั้งครรภ์เสี่ยงมาก \n 5. asbestos \n พบในวัสดุก่อสร้าง เช่น กระเบื้องเก่า หลังคา \n สูดดมเรื้อรังทำให้เกิดมะเร็งเยื่อหุ้มปอด (mesothelioma) ได้ทั้งในคนและสัตว์ \n ผู้สรุปบันทึกว่ามีข้อหลอกที่ระบุว่า mesothelioma เกิดจากปรอท ซึ่งไม่ถูกต้อง ตัวการคือ asbestos \n 6. herbicides (2,4-d) \n ได้รับทาง oral, dermal และ inhalation \n acute dose ไม่สูงเมื่อได้รับทางการกินและผิวหนัง \n chronic exposure จากการสูดดม มีแนวโน้มสัมพันธ์กับ lymphoma ในสุนัข และ non-hodgkin lymphoma ในคน \n ptfe toxicosis จากภาชนะเคลือบกันติดที่ร้อนเกินไปทำให้เกิด pulmonary edema และ pulmonary hemorrhage ในนก และนกไวต่อสารพิษที่สูดดมเป็นพิเศษเพราะระบบหายใจมีประสิทธิภาพสูง ในเหตุการณ์จริงนกถูกพบตายหรือใกล้ตายโดยไม่มีอาการนำมาก่อน \n polymer fume fever เป็นโรคที่เกิดจากการสูดดมผลิตภัณฑ์สลายตัวของ ptfe โดยมีอาการคล้ายไข้หวัดใหญ่ ได้แก่ ไข้ หนาวสั่น ปวดกล้ามเนื้อ ปวดศีรษะ และอ่อนเพลีย แยกจากภาวะอื่นไม่ได้ถ้าไม่มีประวัติการสัมผัส และการทำให้ภาชนะเคลือบ teflon ร้อนเกินไปเป็นกลไกการสัมผัสที่พบบ่อยที่สุดกลไกหนึ่ง \n ปรอทมีสามรูปแบบ คือ elemental หรือ metallic, inorganic และ organic ซึ่งรวม methylmercury และเมื่อปรอทลงสู่สิ่งแวดล้อมแบคทีเรียจะเปลี่ยนให้เป็น methylmercury ที่สะสมทางชีวภาพในปลาและหอย คนจึงได้รับทางการกินสัตว์น้ำ ขณะที่ปรอทธาตุได้รับหลักทางการสูดไอ \n การสูดไอปรอทธาตุก่อพยาธิสภาพที่ปอดเฉียบพลัน โดยการสัมผัสไอปรอทมากกว่า 1 ถึง 2 มิลลิกรัมต่อลูกบาศก์เมตรเพียงไม่กี่ชั่วโมงทำให้เกิด acute chemical bronchiolitis และ pneumonitis และภายใน 2 ชั่วโมงหลังสัมผัสพบ hyaline membrane formation ซึ่งเป็นพยาธิสภาพแบบเดียวกับ ards \n ตะกั่วในบ้านมาจากสี กระสุน ท่อประปาที่มีตะกั่วในข้อต่อและบัดกรี และแบตเตอรี่ตะกั่วกรด และเด็กเล็กกับหญิงตั้งครรภ์เสี่ยงมากที่สุด เพราะเด็กดูดซึมตะกั่วจากปริมาณที่กลืนเข้าไปได้มากกว่าผู้ใหญ่ 4 ถึง 5 เท่า และตะกั่วที่สะสมในกระดูกถูกปล่อยเข้าสู่กระแสเลือดระหว่างตั้งครรภ์แล้วส่งถึงทารกในครรภ์ \n mesothelioma สัมพันธ์กับ asbestos ไม่ใช่ปรอท โดยในสุนัขเลี้ยงที่เป็น mesothelioma พบว่าการที่สมาชิกในบ้านมีอาชีพหรืองานอดิเรกที่สัมผัส asbestos สัมพันธ์กับโรคอย่างมีนัยสำคัญ และเนื้อปอดของสุนัขที่เป็น mesothelioma มีเส้นใย chrysotile asbestos สูงกว่าสุนัขกลุ่มควบคุม \n การใช้สารกำจัดวัชพืชกลุ่ม 2,4-d ในบ้านสัมพันธ์กับ malignant lymphoma ในสุนัข โดยเจ้าของสุนัขที่เป็นมะเร็งต่อมน้ำเหลืองใช้ 2,4-d กับสนามหญ้าบ่อยกว่ากลุ่มควบคุมอย่างมีนัยสำคัญ และความเสี่ยงเพิ่มเป็นสองเท่าเมื่อใช้ตั้งแต่ 4 ครั้งต่อปีขึ้นไป ซึ่งสอดคล้องกับการศึกษาในคนที่พบความสัมพันธ์ระหว่าง 2,4-d กับ non-hodgkin lymphoma'],['one-health--oh-vet-role--สัตว์เลี้ยงเป็นแบบจำลองมะเร็งและ-dog-aging-project','สัตว์เลี้ยงเป็นแบบจำลองมะเร็งและ Dog Aging Project','สัตว์เลี้ยงเป็นแบบจำลองมะเร็งและ dog aging project \n companion animals as cancer models \n สุนัขและแมวมีสรีรวิทยาใกล้เคียงมนุษย์มาก จึงใช้เป็น model ศึกษาโรคได้ \n อายุขัยสั้นกว่า จึงเห็นวงจรของโรคได้เร็วกว่า \n ข้อกังวลคือ การทำหมันทำให้ฮอร์โมนเปลี่ยน ซึ่งมีผลต่อ incidence ของมะเร็ง \n มีข้อมูลมะเร็งในสุนัขจำนวนมาก แต่ยังไม่ได้ validate สำหรับเทียบเคียงกับคนในระดับนั้น \n dog aging project \n ศึกษาความสัมพันธ์ระหว่าง ขนาดตัว igf และอายุขัย \n ใช้สุนัขเพื่อทำความเข้าใจ aging ของมนุษย์ โดยมีเป้าหมายชะลอความชราพร้อมคง metabolism ให้สมดุล \n ยีน igf-1 ในสุนัขพันธุ์ใหญ่กระตุ้นการเจริญเติบโตมากเกินไป จึงทำให้อายุสั้น \n จึงมีความพยายามสร้างยาที่ยับยั้งการสร้างฮอร์โมนนี้ โดยทดลองในสุนัขก่อน \n เหตุผลที่ใช้สุนัขเป็นแบบจำลองศึกษาความชราและโรคของคน คือสุนัขอยู่ในสิ่งแวดล้อมเดียวกับคนและมีระบบดูแลสุขภาพที่ซับซ้อน แต่มีอายุขัยสั้นกว่าคนมาก จึงเป็นโอกาสพิเศษในการหาปัจจัยทางพันธุกรรม สิ่งแวดล้อม และวิถีชีวิตที่สัมพันธ์กับการมีอายุยืนอย่างมีสุขภาพดี \n igf1 เป็นตัวกำหนดขนาดตัวของสุนัขจริง โดย haplotype ของ single-nucleotide polymorphism ใน igf1 หนึ่งชุดพบร่วมกันในสุนัขพันธุ์เล็กทุกพันธุ์และแทบไม่พบในพันธุ์ยักษ์ อย่างไรก็ตามงานชิ้นนี้พิสูจน์ความสัมพันธ์กับขนาดตัว ไม่ได้พิสูจน์ความสัมพันธ์กับอายุขัยโดยตรง']]};
